const GRAINS=[{id:"basmatirice",wiki:"Basmati_rice",emoji:"🍚",name:{en:"Basmati Rice (Basmati Chawal)",hi:"बासमती चावल"},desc:{en:"A long-grain aromatic rice that elongates further on cooking and carries a distinctive fragrance, prized above all other rice in India.",hi:"लंबे दाने वाला सुगंधित चावल जो पकने पर और लंबा हो जाता है, अपनी खास खुशबू के लिए भारत में सबसे ज़्यादा पसंद किया जाता है।"},origin:{en:"Grown at the foothills of the Himalayas across Punjab, Haryana, and parts of Uttar Pradesh, where the climate and soil give it its signature aroma.",hi:"हिमालय की तलहटी में पंजाब, हरियाणा और उत्तर प्रदेश के कुछ हिस्सों में उगाया जाता है, जहाँ की जलवायु और मिट्टी इसे खास खुशबू देती है।"},benefits:{en:"A good source of energy-giving carbohydrates; aged basmati is lower on the glycemic index than most other white rice varieties.",hi:"ऊर्जा देने वाले कार्बोहाइड्रेट का अच्छा स्रोत; पुराना बासमती अधिकांश अन्य सफ़ेद चावल किस्मों से ग्लाइसेमिक इंडेक्स में कम होता है।"},uses:{en:"The rice of choice for biryani, pulao, and jeera rice — its length and fluffiness make it stand out in the plate.",hi:"बिरयानी, पुलाव और जीरा राइस के लिए पहली पसंद — इसकी लंबाई और हल्कापन थाली में अलग ही दिखता है।"},tip:{en:"Rinse until the water runs clear and soak for 20-30 minutes before cooking — this is what gives each grain its separate, elongated shape.",hi:"पानी साफ़ आने तक धोएँ और पकाने से पहले 20-30 मिनट भिगोएँ — इसी से हर दाना अलग और लंबा बनता है।"}},{id:"wheat",wiki:"Wheat",emoji:"🌾",name:{en:"Wheat (Gehun / Atta)",hi:"गेहूं (आटा)"},desc:{en:"India's everyday staple grain, ground into whole-wheat flour and eaten fresh as roti at almost every meal in North India.",hi:"भारत का रोज़मर्रा का मुख्य अनाज, साबुत आटे में पीसकर उत्तर भारत में लगभग हर भोजन में रोटी के रूप में खाया जाता है।"},origin:{en:"Grown extensively across Punjab, Haryana, Uttar Pradesh, and Madhya Pradesh — India is one of the world's largest wheat producers.",hi:"पंजाब, हरियाणा, उत्तर प्रदेश और मध्य प्रदेश में बड़े पैमाने पर उगाया जाता है — भारत दुनिया के सबसे बड़े गेहूं उत्पादकों में से एक है।"},benefits:{en:"Whole wheat retains its bran and germ, providing fiber and B vitamins that refined flour (maida) loses in processing.",hi:"साबुत गेहूं में चोकर और जर्म बरकरार रहते हैं, जो फ़ाइबर और B विटामिन देते हैं जो मैदा प्रसंस्करण में खो जाते हैं।"},uses:{en:"Ground fresh for roti, chapati, paratha, and puri; also the base of sooji (semolina) and dalia (broken wheat).",hi:"रोटी, चपाती, पराठा और पूरी के लिए ताज़ा पिसा जाता है; सूजी और दलिया का भी आधार है।"},tip:{en:"Fresh atta ground at a local chakki (mill) has a shorter shelf life but noticeably better flavor than packaged flour sitting for months.",hi:"स्थानीय चक्की पर पिसा ताज़ा आटा जल्दी खत्म हो जाता है पर महीनों रखे पैक आटे से स्वाद में साफ़ बेहतर होता है।"}},{id:"bajra",wiki:"Pearl_millet",emoji:"🟤",name:{en:"Bajra (Pearl Millet)",hi:"बाजरा"},desc:{en:"A hardy, warming winter-grain millet, most famously ground into thick rotis eaten with ghee and jaggery in Rajasthan and Gujarat.",hi:"सर्दी में खाया जाने वाला गर्म तासीर का मज़बूत बाजरा, राजस्थान और गुजरात में घी-गुड़ के साथ खाई जाने वाली मोटी रोटी के लिए मशहूर।"},origin:{en:"Thrives in the arid, low-rainfall regions of Rajasthan, Gujarat, Haryana, and Maharashtra where other crops struggle.",hi:"राजस्थान, गुजरात, हरियाणा और महाराष्ट्र के सूखे, कम बारिश वाले क्षेत्रों में उगता है जहाँ अन्य फ़सलें मुश्किल से होती हैं।"},benefits:{en:"Rich in iron and fiber, and traditionally considered a warming grain best eaten in winter months.",hi:"आयरन और फ़ाइबर से भरपूर, और परंपरागत रूप से सर्दियों में खाया जाने वाला गर्म तासीर का अनाज माना जाता है।"},uses:{en:"Bajra roti served with white butter and jaggery, and khichdi mixed with moong dal.",hi:"बाजरे की रोटी सफ़ेद मक्खन और गुड़ के साथ, और मूंग दाल के साथ खिचड़ी।"},tip:{en:"The dough is coarse and doesn't hold together like wheat — pat it out by hand between your palms rather than rolling with a pin.",hi:"आटा दरदरा होता है और गेहूं की तरह नहीं बँधता — बेलन की जगह हाथों से थपथपाकर आकार दें।"}},{id:"jowar",wiki:"Sorghum",emoji:"⚪",name:{en:"Jowar (Sorghum)",hi:"ज्वार"},desc:{en:"A pale, mild millet ground into flour for soft rotis, especially central to Maharashtrian and Karnataka home cooking.",hi:"हल्के रंग का, हल्के स्वाद वाला ज्वार, नरम रोटियों के लिए आटे में पीसा जाता है, विशेष रूप से महाराष्ट्रीयन और कर्नाटक के घरेलू खाने में मुख्य।"},origin:{en:"Widely grown across Maharashtra, Karnataka, and Telangana — one of the oldest cultivated millets in India.",hi:"महाराष्ट्र, कर्नाटक और तेलंगाना में व्यापक रूप से उगाया जाता है — भारत में उगाए जाने वाले सबसे पुराने बाजरों में से एक।"},benefits:{en:"Naturally gluten-free and a good source of fiber, often recommended as an alternative grain for those avoiding wheat.",hi:"स्वाभाविक रूप से ग्लूटेन-मुक्त और फ़ाइबर का अच्छा स्रोत, अक्सर गेहूं से बचने वालों के लिए वैकल्पिक अनाज के रूप में सुझाया जाता है।"},uses:{en:"Jowar bhakri (roti), jowar upma, and roasted jowar puffs (lahya) as a light snack.",hi:"ज्वार की भाकरी (रोटी), ज्वार उपमा, और भुने ज्वार के लाहया हल्के नाश्ते के रूप में।"},tip:{en:"Jowar dough needs to be kneaded with hot water and shaped while still warm, or it cracks and falls apart when rolled.",hi:"ज्वार का आटा गरम पानी से गूंधना चाहिए और गरम रहते ही आकार देना चाहिए, वरना बेलते समय टूट जाता है।"}},{id:"ragi",wiki:"Finger_millet",emoji:"🟫",name:{en:"Ragi (Finger Millet)",hi:"रागी (नाचनी)"},desc:{en:"A deep reddish-brown millet ground into flour, a South Indian staple famous for ragi mudde and a popular first food for babies.",hi:"गहरे भूरे-लाल रंग का बाजरा जो आटे में पिसता है, रागी मुद्दे के लिए मशहूर दक्षिण भारतीय मुख्य अनाज और शिशुओं के लिए लोकप्रिय पहला आहार।"},origin:{en:"A traditional crop of Karnataka, where it is central to daily cooking, also grown in Tamil Nadu and parts of the Himalayas.",hi:"कर्नाटक की पारंपरिक फ़सल, जहाँ यह रोज़मर्रा के खाने का केंद्र है, तमिलनाडु और हिमालय के कुछ हिस्सों में भी उगाई जाती है।"},benefits:{en:"One of the richest plant sources of calcium among grains, and traditionally given to growing children and nursing mothers.",hi:"अनाजों में कैल्शियम के सबसे समृद्ध पौधे-स्रोतों में से एक, और परंपरागत रूप से बढ़ते बच्चों और स्तनपान कराने वाली माताओं को दिया जाता है।"},uses:{en:"Ragi mudde (steamed dumplings), ragi dosa, ragi porridge for babies, and ragi cookies.",hi:"रागी मुद्दे (भाप में पकी लोइयाँ), रागी डोसा, शिशुओं के लिए रागी दलिया, और रागी बिस्किट।"},tip:{en:"Roast ragi flour lightly in a dry pan before using in porridge — it removes any raw smell and deepens the nutty flavor.",hi:"दलिये में इस्तेमाल करने से पहले रागी के आटे को सूखे तवे पर हल्का भून लें — इससे कच्ची गंध जाती है और स्वाद गहरा हो जाता है।"}},{id:"makka",wiki:"Maize",emoji:"🌽",name:{en:"Makka (Maize / Corn)",hi:"मक्का"},desc:{en:"Yellow corn ground into flour for the iconic makki di roti of Punjab, and eaten fresh off the cob as roadside bhutta across India.",hi:"पीली मक्का जो पंजाब की मशहूर मक्की दी रोटी के लिए आटे में पिसती है, और पूरे भारत में सड़क किनारे भुट्टे के रूप में ताज़ा खाई जाती है।"},origin:{en:"Grown widely across Punjab, Bihar, Karnataka, and Madhya Pradesh in both rain-fed and irrigated conditions.",hi:"पंजाब, बिहार, कर्नाटक और मध्य प्रदेश में बारिश और सिंचाई दोनों स्थितियों में व्यापक रूप से उगाई जाती है।"},benefits:{en:"A good source of fiber and antioxidants; naturally gluten-free, making makki atta a common wheat substitute.",hi:"फ़ाइबर और एंटीऑक्सीडेंट का अच्छा स्रोत; स्वाभाविक रूप से ग्लूटेन-मुक्त, जिससे मक्की का आटा एक आम गेहूं विकल्प बनता है।"},uses:{en:"Makki di roti with sarson da saag, roasted bhutta with lemon and chili, and corn added to pulao.",hi:"सरसों के साग के साथ मक्की दी रोटी, नींबू-मिर्च के साथ भुना भुट्टा, और पुलाव में मिलाई गई मक्का।"},tip:{en:"Makki atta has no gluten to bind it — press the dough out on a damp cloth or plastic sheet rather than rolling with a pin.",hi:"मक्की के आटे में बाँधने वाला ग्लूटेन नहीं होता — बेलन की जगह गीले कपड़े या प्लास्टिक शीट पर हाथ से दबाकर आकार दें।"}},{id:"barley",wiki:"Barley",emoji:"🌿",name:{en:"Jau (Barley)",hi:"जौ"},desc:{en:"An ancient grain used in India mostly as roasted flour (sattu) or a light, easily digestible porridge for recovery and fasting.",hi:"एक प्राचीन अनाज जो भारत में ज़्यादातर भुने आटे (सत्तू) या हल्के, आसानी से पचने वाले दलिये के रूप में स्वास्थ्य-लाभ और उपवास के लिए उपयोग होता है।"},origin:{en:"Grown in the cooler regions of Uttar Pradesh, Rajasthan, Punjab, and parts of the Himalayas.",hi:"उत्तर प्रदेश, राजस्थान, पंजाब और हिमालय के ठंडे क्षेत्रों में उगाई जाती है।"},benefits:{en:"High in fiber and traditionally recommended in Ayurveda as a light, cooling grain suited to convalescence and fasting.",hi:"फ़ाइबर से भरपूर और आयुर्वेद में परंपरागत रूप से हल्के, ठंडे तासीर वाले अनाज के रूप में स्वास्थ्य-लाभ और उपवास के लिए सुझाया जाता है।"},uses:{en:"Sattu drinks and parathas, barley water as a cooling summer drink, and barley khichdi.",hi:"सत्तू के पेय और पराठे, गर्मियों में ठंडक देने वाला जौ का पानी, और जौ की खिचड़ी।"},tip:{en:"Roasted barley (sattu) mixed with cold water, a pinch of salt, and lemon makes one of the fastest, most cooling summer drinks.",hi:"भुना जौ (सत्तू) ठंडे पानी, चुटकी भर नमक और नींबू के साथ मिलाकर गर्मियों का सबसे तेज़, ठंडक भरा पेय बनता है।"}},{id:"foxtailmillet",wiki:"Foxtail_millet",emoji:"🌱",name:{en:"Kangni (Foxtail Millet)",hi:"कंगनी (काकुन)"},desc:{en:"A small, quick-cooking millet with a mild, slightly nutty taste, increasingly popular as a rice substitute in health-focused cooking.",hi:"छोटा, जल्दी पकने वाला बाजरा जिसका स्वाद हल्का और थोड़ा मेवे जैसा होता है, स्वास्थ्य-केंद्रित खाने में चावल के विकल्प के रूप में तेज़ी से लोकप्रिय।"},origin:{en:"One of the oldest cultivated millets in India, traditionally grown across Karnataka, Andhra Pradesh, and Tamil Nadu.",hi:"भारत में उगाए जाने वाले सबसे पुराने बाजरों में से एक, परंपरागत रूप से कर्नाटक, आंध्र प्रदेश और तमिलनाडु में उगाया जाता है।"},benefits:{en:"Low glycemic index and a good source of protein among grains, often included in millet-based diabetic-friendly diets.",hi:"कम ग्लाइसेमिक इंडेक्स और अनाजों में प्रोटीन का अच्छा स्रोत, अक्सर मधुमेह के अनुकूल बाजरा-आधारित आहार में शामिल किया जाता है।"},uses:{en:"Cooked like rice for pulao and khichdi, or ground into flour for dosa and idli batter.",hi:"पुलाव और खिचड़ी के लिए चावल की तरह पकाई जाती है, या डोसा और इडली के घोल के लिए आटे में पिसी जाती है।"},tip:{en:"Rinse well and soak for 30 minutes before cooking — it cooks faster than rice and can turn mushy if boiled too long.",hi:"पकाने से पहले अच्छी तरह धोकर 30 मिनट भिगोएँ — यह चावल से जल्दी पकती है और ज़्यादा उबालने पर गीली हो सकती है।"}},{id:"kodomillet",wiki:"Kodo_millet",emoji:"🟨",name:{en:"Kodo Millet (Kodra)",hi:"कोदो (कोदरा)"},desc:{en:"A small, drought-resistant millet with a light, fluffy texture once cooked, traditionally eaten during fasting days.",hi:"सूखे के प्रति सहनशील छोटा बाजरा जिसकी बनावट पकने पर हल्की और फूली हुई होती है, परंपरागत रूप से व्रत के दिनों में खाया जाता है।"},origin:{en:"Cultivated in tribal belts of Madhya Pradesh, Chhattisgarh, Odisha, and Tamil Nadu, often in poor, dry soils.",hi:"मध्य प्रदेश, छत्तीसगढ़, ओडिशा और तमिलनाडु के आदिवासी क्षेत्रों में, अक्सर खराब, सूखी मिट्टी में उगाया जाता है।"},benefits:{en:"High in fiber and traditionally considered easy to digest, which is part of why it is favored for religious fasting.",hi:"फ़ाइबर में उच्च और परंपरागत रूप से आसानी से पचने वाला माना जाता है, यही वजह है कि यह व्रत में पसंद किया जाता है।"},uses:{en:"Kodo millet khichdi and upma during navratri or other fasting periods, and as a rice substitute in daily meals.",hi:"नवरात्रि या अन्य व्रत के दौरान कोदो की खिचड़ी और उपमा, और रोज़ के खाने में चावल के विकल्प के रूप में।"},tip:{en:"Toast the dry millet briefly before cooking to bring out a nuttier flavor and keep the grains from clumping.",hi:"पकाने से पहले सूखे बाजरे को थोड़ा भून लें, इससे स्वाद और मेवे जैसा होता है और दाने चिपकते नहीं।"}},{id:"chana",wiki:"Chickpea",emoji:"🫘",name:{en:"Chana (Bengal Gram)",hi:"चना"},desc:{en:"Small brown chickpeas, ground into besan (gram flour) that touches nearly every Indian kitchen — from pakoras to sweets.",hi:"छोटे भूरे चने, जो बेसन में पिसकर लगभग हर भारतीय रसोई को छूते हैं — पकौड़ों से लेकर मिठाइयों तक।"},origin:{en:"Grown extensively in Madhya Pradesh, Maharashtra, Rajasthan, and Uttar Pradesh — India is the world's largest chickpea producer.",hi:"मध्य प्रदेश, महाराष्ट्र, राजस्थान और उत्तर प्रदेश में बड़े पैमाने पर उगाया जाता है — भारत दुनिया का सबसे बड़ा चना उत्पादक है।"},benefits:{en:"A strong plant-based source of protein and fiber, making besan and roasted chana popular for sustained energy.",hi:"पौधे-आधारित प्रोटीन और फ़ाइबर का मज़बूत स्रोत, जिससे बेसन और भुना चना ऊर्जा बनाए रखने के लिए लोकप्रिय है।"},uses:{en:"Besan for pakoras, kadhi, and ladoos; whole chana boiled for chana chaat or roasted as a snack.",hi:"पकौड़े, कढ़ी और लड्डू के लिए बेसन; उबले साबुत चने चाट के लिए या भुनकर नाश्ते के रूप में।"},tip:{en:"Sift besan before using in batters — it clumps easily, and sifting gives a smoother, lump-free mix.",hi:"घोल में इस्तेमाल करने से पहले बेसन को छान लें — यह आसानी से गुठलियाँ बनाता है, छानने से मिश्रण चिकना और बिना गुठली का बनता है।"}},{id:"buckwheat",wiki:"Buckwheat",emoji:"🔺",name:{en:"Kuttu (Buckwheat)",hi:"कुट्टू"},desc:{en:"Technically a seed rather than a true grain, ground into flour and eaten almost exclusively during religious fasting.",hi:"तकनीकी रूप से अनाज नहीं बल्कि बीज, आटे में पिसकर लगभग पूरी तरह धार्मिक व्रत के दौरान खाया जाता है।"},origin:{en:"Grown in the hilly regions of Uttarakhand, Himachal Pradesh, and Jammu & Kashmir.",hi:"उत्तराखंड, हिमाचल प्रदेश और जम्मू-कश्मीर के पहाड़ी क्षेत्रों में उगाई जाती है।"},benefits:{en:'Naturally gluten-free and a source of protein and fiber — accepted as a "fasting food" in traditions where regular grains are avoided.',hi:'स्वाभाविक रूप से ग्लूटेन-मुक्त और प्रोटीन-फ़ाइबर का स्रोत — उन परंपराओं में "व्रत का भोजन" माना जाता है जहाँ सामान्य अनाज नहीं खाए जाते।'},uses:{en:"Kuttu ki puri and kuttu paratha during navratri fasts, and pakoras made from kuttu batter.",hi:"नवरात्रि व्रत में कुट्टू की पूरी और कुट्टू पराठा, और कुट्टू के घोल से बने पकौड़े।"},tip:{en:"Kuttu dough is sticky and hard to roll — mash boiled potato into it, which both binds the dough and softens the final puri or paratha.",hi:"कुट्टू का आटा चिपचिपा होता है और बेलना मुश्किल — उबला आलू मसलकर मिलाएँ, इससे आटा बँधता भी है और पूरी-पराठा नरम भी बनता है।"}},{id:"sooji",wiki:"Semolina",emoji:"🟡",name:{en:"Sooji / Rava (Semolina)",hi:"सूजी / रवा"},desc:{en:"Coarsely milled wheat, the quick-cooking base for both the beloved breakfast upma and the festive sweet halwa.",hi:"दरदरा पिसा गेहूं, प्रिय नाश्ते उपमा और त्योहारी मिठाई हलवे दोनों का जल्दी पकने वाला आधार।"},origin:{en:"Produced by milling the hardest part of the wheat grain; widely made across the same wheat belts as regular atta.",hi:"गेहूं के दाने के सबसे सख़्त हिस्से को पीसकर बनाया जाता है; सामान्य आटे जैसे ही गेहूं-उत्पादक क्षेत्रों में व्यापक रूप से बनाया जाता है।"},benefits:{en:"Lower in fiber than whole wheat since the bran is removed, but a quick source of energy that cooks in minutes.",hi:"चोकर हटाए जाने से साबुत गेहूं से फ़ाइबर में कम, पर मिनटों में पकने वाला ऊर्जा का त्वरित स्रोत।"},uses:{en:"Upma, rava kesari (sweet halwa), rava dosa, and as a crisp coating for shallow-fried fish or vegetables.",hi:"उपमा, रवा केसरी (मीठा हलवा), रवा डोसा, और तली मछली या सब्ज़ियों पर कुरकुरी परत के लिए।"},tip:{en:"Dry-roast sooji in a pan until lightly golden and fragrant before adding liquid — this is what keeps upma and halwa from turning gluey.",hi:"तरल डालने से पहले सूजी को तवे पर हल्का सुनहरा और खुशबूदार होने तक सूखा भून लें — इसी से उपमा और हलवा चिपचिपा नहीं होता।"}},{id:"poha",wiki:"Flattened_rice",emoji:"🍘",name:{en:"Poha (Flattened Rice)",hi:"पोहा"},desc:{en:"Parboiled rice that has been flattened and dried, needing no real cooking — just a rinse before it softens for breakfast.",hi:"उबले चावल को चपटा और सुखाकर बनाया जाता है, असली पकाने की ज़रूरत नहीं — नाश्ते के लिए नरम होने से पहले बस धोना काफ़ी है।"},origin:{en:"Made across rice-growing regions, though the poha breakfast dish is most identified with Madhya Pradesh and Maharashtra.",hi:"चावल उगाने वाले क्षेत्रों में बनाया जाता है, हालांकि पोहा नाश्ता मध्य प्रदेश और महाराष्ट्र से सबसे ज़्यादा जुड़ा है।"},benefits:{en:"Light and easy to digest since it is already parboiled and flattened, making it a common choice for a quick, gentle breakfast.",hi:"पहले से उबला और चपटा होने के कारण हल्का और आसानी से पचने वाला, जिससे यह त्वरित, हल्के नाश्ते के लिए आम पसंद है।"},uses:{en:"Indori poha with onions and sev, Maharashtrian kanda poha, and poha chivda as a savory snack mix.",hi:"प्याज़ और सेव के साथ इंदौरी पोहा, महाराष्ट्रीयन कांदा पोहा, और नमकीन स्नैक मिश्रण के रूप में पोहा चिवड़ा।"},tip:{en:"Rinse poha briefly in a strainer under running water rather than soaking it — over-soaking turns it mushy before it even hits the pan.",hi:"भिगोने की बजाय पोहे को छलनी में बहते पानी के नीचे थोड़ा धो लें — ज़्यादा भिगोने से तवे पर आने से पहले ही यह गीला हो जाता है।"}},{id:"sabudana",wiki:"Tapioca",emoji:"⚪",name:{en:"Sabudana (Tapioca Pearls)",hi:"साबूदाना"},desc:{en:"Small pearls made from tapioca starch, chewy and starchy once soaked — a fasting-food staple, though not a true grain botanically.",hi:"टैपिओका स्टार्च से बने छोटे मोती, भिगोने पर चबाने योग्य और स्टार्चयुक्त — व्रत के भोजन का मुख्य हिस्सा, हालांकि वनस्पति विज्ञान की दृष्टि से असली अनाज नहीं।"},origin:{en:"Processed mainly in Salem, Tamil Nadu, from the cassava (tapioca) root grown in the region.",hi:"मुख्य रूप से तमिलनाडु के सलेम में क्षेत्र में उगाई गई कसावा (टैपिओका) जड़ से प्रसंस्कृत।"},benefits:{en:"Mostly starch with little fiber or protein on its own, which is why it is traditionally paired with peanuts for a fuller fasting meal.",hi:"अकेले ज़्यादातर स्टार्च है, फ़ाइबर या प्रोटीन कम — इसीलिए इसे परंपरागत रूप से पूर्ण व्रत भोजन के लिए मूंगफली के साथ मिलाया जाता है।"},uses:{en:"Sabudana khichdi and sabudana vada during navratri and other fasts, and sabudana kheer as a dessert.",hi:"नवरात्रि और अन्य व्रत में साबूदाना खिचड़ी और साबूदाना वड़ा, और मिठाई के रूप में साबूदाना खीर।"},tip:{en:"Soak just enough water to cover the pearls, not more — too much water makes them mushy instead of separate and fluffy after cooking.",hi:"मोतियों को ढकने भर ही पानी में भिगोएँ, ज़्यादा नहीं — ज़्यादा पानी पकने के बाद इन्हें अलग-फूला होने की बजाय गीला बना देता है।"}}],LENTILS=[{id:"toordal",wiki:"Pigeon_pea",emoji:"🟡",name:{en:"Toor Dal (Arhar Dal)",hi:"तूर दाल (अरहर दाल)"},desc:{en:"Split, oily-skinned yellow lentils that cook down soft and slightly sweet — the everyday dal in most North and West Indian homes.",hi:"चिकनी छिलके वाली पीली दाल जो पकने पर नरम और हल्की मीठी हो जाती है — उत्तर और पश्चिम भारत के ज़्यादातर घरों की रोज़ाना की दाल।"},origin:{en:"India grows and consumes the vast majority of the world's toor dal, especially across Maharashtra, Karnataka, and Uttar Pradesh.",hi:"भारत दुनिया की अधिकांश तूर दाल उगाता और खाता है, विशेष रूप से महाराष्ट्र, कर्नाटक और उत्तर प्रदेश में।"},benefits:{en:"A solid plant-based protein source, and one of the most digestible lentils, which is why it's often the first dal given to young children.",hi:"ठोस पौधा-आधारित प्रोटीन स्रोत, और सबसे आसानी से पचने वाली दालों में से एक, यही वजह है कि यह अक्सर छोटे बच्चों को दी जाने वाली पहली दाल है।"},uses:{en:"Dal tadka, sambar, and the base of most everyday North Indian and South Indian dal preparations.",hi:"दाल तड़का, सांभर, और अधिकांश रोज़ाना उत्तर व दक्षिण भारतीय दाल व्यंजनों का आधार।"},tip:{en:"A few drops of oil added to the cooking water keeps the dal from foaming over and boiling out of the pot.",hi:"पकाने के पानी में कुछ बूँद तेल डालने से दाल उफनकर बर्तन से बाहर नहीं गिरती।"}},{id:"moongdal",wiki:"Mung_bean",emoji:"🟨",name:{en:"Moong Dal (Split Yellow Gram)",hi:"मूंग दाल (पीली)"},desc:{en:"A light, quick-cooking split lentil, gentle enough on the stomach to be the first solid food given to infants and the sick.",hi:"हल्की, जल्दी पकने वाली दाल, पेट के लिए इतनी हल्की कि शिशुओं और बीमार लोगों को दिया जाने वाला पहला ठोस भोजन बनती है।"},origin:{en:"Grown widely across Rajasthan, Maharashtra, Andhra Pradesh, and Madhya Pradesh.",hi:"राजस्थान, महाराष्ट्र, आंध्र प्रदेश और मध्य प्रदेश में व्यापक रूप से उगाई जाती है।"},benefits:{en:"Easy to digest and rich in protein and folate, widely recommended in Ayurveda as a light, balancing food for recovery.",hi:"आसानी से पचने वाली और प्रोटीन-फोलेट से भरपूर, आयुर्वेद में स्वास्थ्य-लाभ के लिए हल्के, संतुलित भोजन के रूप में व्यापक रूप से सुझाई जाती है।"},uses:{en:"Moong dal khichdi, moong dal halwa, and thin dal for the unwell or fasting.",hi:"मूंग दाल की खिचड़ी, मूंग दाल का हलवा, और बीमार या व्रत में हल्की दाल।"},tip:{en:"Dry-roasting the dal lightly before cooking gives khichdi a deeper, nuttier flavor and helps the grains stay separate.",hi:"पकाने से पहले दाल को हल्का सूखा भूनने से खिचड़ी में गहरा, मेवे जैसा स्वाद आता है और दाने अलग-अलग रहते हैं।"}},{id:"sabutmoong",wiki:"Mung_bean",emoji:"🟢",name:{en:"Sabut Moong (Whole Green Gram)",hi:"साबुत मूंग"},desc:{en:"The whole, unsplit green mung bean with its skin intact, firmer and earthier than its split yellow form.",hi:"साबुत, बिना छिली हरी मूंग जिसका छिलका बरकरार रहता है, अपने पीले छिलके वाले रूप से ज़्यादा सख़्त और मिट्टी जैसे स्वाद वाली।"},origin:{en:"Cultivated across Rajasthan, Maharashtra, and central India, often the same crop later split and polished into moong dal.",hi:"राजस्थान, महाराष्ट्र और मध्य भारत में उगाई जाती है, अक्सर यही फ़सल बाद में छीलकर और चमकाकर मूंग दाल बनती है।"},benefits:{en:"Higher in fiber than split moong dal since the skin is intact, and a favorite for sprouting due to its high protein content.",hi:"छिलका बरकरार होने से छिली मूंग दाल से फ़ाइबर में ज़्यादा, और अपने उच्च प्रोटीन कारण अंकुरण के लिए पसंदीदा।"},uses:{en:"Sprouted for salads and chaat, cooked whole for moong curry, and ground soaked for moong dal cheela (savory pancakes).",hi:"सलाद और चाट के लिए अंकुरित, साबुत मूंग करी के लिए पकाई जाती है, और भिगोकर पीसने पर मूंग दाल चीला (नमकीन पैनकेक) बनती है।"},tip:{en:"Soak overnight before cooking or sprouting — this cuts cooking time significantly and makes the sprouts come up faster and more evenly.",hi:"पकाने या अंकुरित करने से पहले रातभर भिगोएँ — इससे पकने का समय काफ़ी कम हो जाता है और अंकुर जल्दी व समान रूप से आते हैं।"}},{id:"chanadal",wiki:"Chana_dal",emoji:"🟠",name:{en:"Chana Dal (Split Bengal Gram)",hi:"चना दाल"},desc:{en:"Split, skinned Bengal gram with a firm bite and slightly nutty, sweet flavor — different from the whole chickpea it comes from.",hi:"छिलका उतरी, बँटी बंगाल चना दाल जिसका दाना सख़्त और स्वाद हल्का मेवा जैसा मीठा होता है — साबुत चने से अलग जिससे यह बनती है।"},origin:{en:"Made by splitting and polishing whole desi chana, produced in the same belts — Madhya Pradesh, Maharashtra, and Rajasthan.",hi:"साबुत देसी चने को बाँटकर और चमकाकर बनाई जाती है, उन्हीं क्षेत्रों में — मध्य प्रदेश, महाराष्ट्र और राजस्थान में उत्पादित।"},benefits:{en:"High in protein and fiber, and its low glycemic index makes it a commonly recommended dal for balanced blood sugar.",hi:"प्रोटीन और फ़ाइबर में उच्च, और इसका कम ग्लाइसेमिक इंडेक्स इसे संतुलित रक्त शर्करा के लिए अक्सर सुझाई जाने वाली दाल बनाता है।"},uses:{en:"Chana dal curry, the stuffing for puran poli and holige, and ground into flour for certain snacks.",hi:"चना दाल की सब्ज़ी, पुरण पोली और होलिगे की भरावन, और कुछ नाश्तों के लिए आटे में पिसती है।"},tip:{en:"Chana dal holds its shape well and takes longer to soften than toor or moong dal — soak for at least an hour for even cooking.",hi:"चना दाल अपना आकार अच्छी तरह बनाए रखती है और तूर या मूंग दाल से नरम होने में ज़्यादा समय लेती है — समान रूप से पकाने के लिए कम से कम एक घंटा भिगोएँ।"}},{id:"uraddal",wiki:"Vigna_mungo",emoji:"⚪",name:{en:"Urad Dal (Split White Gram)",hi:"उड़द दाल (धुली)"},desc:{en:"Split, skinned black gram, creamy and slightly gelatinous once cooked — the backbone of South Indian batters.",hi:"छिलका उतरी उड़द दाल, पकने पर मलाईदार और हल्की चिपचिपी — दक्षिण भारतीय घोल की रीढ़।"},origin:{en:"Widely grown across Andhra Pradesh, Madhya Pradesh, Tamil Nadu, and Maharashtra.",hi:"आंध्र प्रदेश, मध्य प्रदेश, तमिलनाडु और महाराष्ट्र में व्यापक रूप से उगाई जाती है।"},benefits:{en:"Rich in protein and, uniquely among lentils, prized for the natural fermentation it enables when soaked and ground.",hi:"प्रोटीन से भरपूर और दालों में खास तौर पर, भिगोने और पीसने पर प्राकृतिक किण्वन के लिए मूल्यवान।"},uses:{en:"Ground with rice for idli and dosa batter, and the star of dal makhani and urad dal tadka.",hi:"चावल के साथ पीसकर इडली-डोसा का घोल, और दाल मखनी व उड़द दाल तड़के की मुख्य सामग्री।"},tip:{en:"For idli or dosa batter, grind urad dal to a light, fluffy paste — the air whipped in during grinding is what makes the batter rise on fermenting.",hi:"इडली या डोसा के घोल के लिए उड़द दाल को हल्का, फूला हुआ पीसें — पीसते समय मिली हवा ही किण्वन पर घोल को फुलाती है।"}},{id:"sabuturad",wiki:"Vigna_mungo",emoji:"⚫",name:{en:"Sabut Urad (Whole Black Gram)",hi:"साबुत उड़द (काली दाल)"},desc:{en:"The whole, unsplit black gram with its dark skin on, slow-cooked into the rich, buttery dal that anchors dal makhani.",hi:"साबुत उड़द जिसका काला छिलका बरकरार रहता है, धीमी आँच पर पकाकर दाल मखनी का आधार बनने वाली गाढ़ी, मक्खनी दाल बनती है।"},origin:{en:"Grown across the same belts as split urad — Madhya Pradesh, Maharashtra, Andhra Pradesh, and Tamil Nadu.",hi:"छिली उड़द दाल जैसे ही क्षेत्रों में उगाई जाती है — मध्य प्रदेश, महाराष्ट्र, आंध्र प्रदेश और तमिलनाडु।"},benefits:{en:"Higher in fiber than the split version since the skin remains, and its slow-cooked richness makes it a hearty, protein-dense winter dal.",hi:"छिलका बरकरार रहने से छिली दाल से फ़ाइबर में ज़्यादा, और धीमी आँच पर पकने से यह सर्दियों की भरपूर, प्रोटीन-युक्त दाल बनती है।"},uses:{en:"Dal makhani, langar-style maa ki dal, and combined with rajma in mixed dal preparations.",hi:"दाल मखनी, लंगर वाली माँ की दाल, और राजमा के साथ मिली-जुली दाल व्यंजनों में।"},tip:{en:"Real dal makhani depends on slow cooking, ideally for hours on low heat — the long simmer is what breaks the lentils down into that signature velvety texture.",hi:"असली दाल मखनी धीमी आँच पर घंटों पकने पर निर्भर करती है — यही लंबा पकना दाल को उस खास मखमली बनावट में तोड़ता है।"}},{id:"masoordal",wiki:"Lentil",emoji:"🔴",name:{en:"Masoor Dal (Red Lentil)",hi:"मसूर दाल"},desc:{en:"Small, quick-cooking lentils that turn golden-orange once split and skinned, valued for how fast they go from pot to plate.",hi:"छोटी, जल्दी पकने वाली दाल जो छिलका उतरने और बँटने पर सुनहरी-नारंगी हो जाती है, बर्तन से थाली तक पहुँचने की तेज़ी के लिए पसंद की जाती है।"},origin:{en:"Grown in Madhya Pradesh, Uttar Pradesh, and Bihar, often as a winter crop rotated with wheat.",hi:"मध्य प्रदेश, उत्तर प्रदेश और बिहार में उगाई जाती है, अक्सर गेहूं के साथ सर्दियों की फ़सल के रूप में।"},benefits:{en:"One of the fastest-cooking lentils and a good iron and protein source, making it a practical everyday choice.",hi:"सबसे जल्दी पकने वाली दालों में से एक और आयरन-प्रोटीन का अच्छा स्रोत, जिससे यह रोज़ाना के लिए व्यावहारिक विकल्प बनती है।"},uses:{en:"Masoor dal tadka, mixed into vegetable dals for quick thickness, and popular in soups for its fast cooking time.",hi:"मसूर दाल तड़का, जल्दी गाढ़ेपन के लिए सब्ज़ी दालों में मिलाई जाती है, और अपने जल्दी पकने के कारण सूप में लोकप्रिय।"},tip:{en:"Masoor dal needs no soaking and cooks in about 15-20 minutes — the dal to reach for when short on time.",hi:"मसूर दाल को भिगोने की ज़रूरत नहीं और लगभग 15-20 मिनट में पक जाती है — समय कम होने पर यही दाल बनाएँ।"}},{id:"rajma",wiki:"Kidney_bean",emoji:"🫘",name:{en:"Rajma (Kidney Beans)",hi:"राजमा"},desc:{en:"Large, deep red kidney-shaped beans, slow-cooked into a thick, hearty curry beloved across North India.",hi:"बड़ी, गहरे लाल गुर्दे के आकार की फलियाँ, धीमी आँच पर पकाकर उत्तर भारत में प्रिय गाढ़ी, भरपूर करी बनती हैं।"},origin:{en:"Grown extensively in Jammu & Kashmir and Himachal Pradesh — Kashmiri rajma is especially prized for its size and softness.",hi:"जम्मू-कश्मीर और हिमाचल प्रदेश में बड़े पैमाने पर उगाई जाती हैं — कश्मीरी राजमा अपने आकार और नरमी के लिए विशेष रूप से मूल्यवान।"},benefits:{en:"A dense source of plant protein and fiber, and central to the beloved rajma-chawal combination as a complete, balanced meal.",hi:"पौधा-प्रोटीन और फ़ाइबर का घना स्रोत, और प्रिय राजमा-चावल संयोजन का केंद्र जो एक संपूर्ण, संतुलित भोजन है।"},uses:{en:"Rajma masala served with steamed rice — one of the most iconic North Indian weekend comfort meals.",hi:"चावल के साथ राजमा मसाला — उत्तर भारत के सबसे प्रतिष्ठित सप्ताहांत आरामदायक भोजनों में से एक।"},tip:{en:"Soak rajma for at least 6-8 hours or overnight — unsoaked beans can take hours to cook soft and may still stay firm in the center.",hi:"राजमा को कम से कम 6-8 घंटे या रातभर भिगोएँ — बिना भिगोई फलियाँ नरम होने में घंटों लगा सकती हैं और बीच में सख़्त रह सकती हैं।"}},{id:"kabulichana",wiki:"Chickpea",emoji:"🟤",name:{en:"Kabuli Chana (White Chickpeas)",hi:"काबुली चना"},desc:{en:"Larger, paler, and smoother-skinned than desi chana, this is the chickpea behind the beloved street food chole.",hi:"देसी चने से बड़ा, हल्का और चिकना छिलका, यही चना प्रिय स्ट्रीट फूड छोले के पीछे है।"},origin:{en:"Grown across Madhya Pradesh, Rajasthan, and Uttar Pradesh, and widely imported to meet the demand for chole and hummus.",hi:"मध्य प्रदेश, राजस्थान और उत्तर प्रदेश में उगाया जाता है, और छोले व हुम्मुस की माँग पूरी करने के लिए व्यापक रूप से आयातित।"},benefits:{en:"A good source of protein and fiber, and its low glycemic index makes chole a filling meal that keeps energy steady.",hi:"प्रोटीन और फ़ाइबर का अच्छा स्रोत, और इसका कम ग्लाइसेमिक इंडेक्स छोले को एक भरपूर भोजन बनाता है जो ऊर्जा को स्थिर रखता है।"},uses:{en:"Chole bhature, chana chaat, and boiled kabuli chana tossed into salads.",hi:"छोले भटूरे, चना चाट, और उबले काबुली चने सलाद में डाले जाते हैं।"},tip:{en:"A pinch of baking soda in the soaking water softens kabuli chana faster and gives chole its deep, dark restaurant-style color when boiled with the skins of tea bags.",hi:"भिगोने के पानी में एक चुटकी बेकिंग सोडा काबुली चने को जल्दी नरम करता है, और चाय की पत्ती की पोटली के साथ उबालने पर छोले को गहरा, रेस्टोरेंट जैसा रंग मिलता है।"}},{id:"lobia",wiki:"Vigna_unguiculata",emoji:"⚪",name:{en:"Lobia (Black-Eyed Peas)",hi:"लोबिया"},desc:{en:"Cream-colored beans with a distinctive black spot, cooked into a mild, quick-cooking curry with a slightly earthy flavor.",hi:"क्रीम रंग की फलियाँ जिन पर एक खास काला निशान होता है, हल्की, जल्दी पकने वाली और थोड़ी मिट्टी जैसे स्वाद वाली करी में पकाई जाती हैं।"},origin:{en:"Grown across Uttar Pradesh, Madhya Pradesh, and parts of South India, often as a rotation crop.",hi:"उत्तर प्रदेश, मध्य प्रदेश और दक्षिण भारत के कुछ हिस्सों में उगाई जाती हैं, अक्सर फ़सल चक्र के रूप में।"},benefits:{en:"High in fiber and folate, and unlike many beans, cooks relatively quickly without an extended soak.",hi:"फ़ाइबर और फोलेट में उच्च, और कई फलियों के विपरीत, बिना ज़्यादा भिगोए अपेक्षाकृत जल्दी पक जाती हैं।"},uses:{en:"Lobia curry with onion-tomato masala, and sprouted lobia added to salads and chaats.",hi:"प्याज़-टमाटर मसाले के साथ लोबिया करी, और अंकुरित लोबिया सलाद व चाट में डाली जाती है।"},tip:{en:"A short 2-3 hour soak is usually enough for lobia — over-soaking can make the skins split and slip off during cooking.",hi:"लोबिया के लिए 2-3 घंटे की भिगोना आमतौर पर काफ़ी है — ज़्यादा भिगोने से पकाते समय छिलके फट कर उतर सकते हैं।"}},{id:"mothdal",wiki:"Vigna_aconitifolia",emoji:"🟫",name:{en:"Moth Dal (Matki)",hi:"मोठ (मटकी)"},desc:{en:"Small, drought-hardy beans, especially loved in Maharashtra and Rajasthan as sprouts in a spiced usal curry.",hi:"सूखे के प्रति सहनशील छोटी फलियाँ, विशेष रूप से महाराष्ट्र और राजस्थान में मसालेदार उसल करी के रूप में अंकुरित पसंद की जाती हैं।"},origin:{en:"Suited to the arid soils of Rajasthan and Maharashtra, where it survives with minimal water.",hi:"राजस्थान और महाराष्ट्र की सूखी मिट्टी के लिए उपयुक्त, जहाँ यह कम पानी में भी जीवित रहती है।"},benefits:{en:"One of the highest-protein lentils among common varieties, and popular sprouted for an extra nutrient boost.",hi:"आम किस्मों में सबसे ज़्यादा प्रोटीन वाली दालों में से एक, और अतिरिक्त पोषण के लिए अंकुरित करके लोकप्रिय।"},uses:{en:"Misal pav (as sprouted matki usal), moth dal ki sabzi, and as a crunchy sprouted salad topping.",hi:"मिसल पाव (अंकुरित मटकी उसल के रूप में), मोठ दाल की सब्ज़ी, और कुरकुरी अंकुरित सलाद के ऊपर।"},tip:{en:"Sprout moth dal by soaking overnight, then keeping it damp and covered for a day or two — small white sprouts mean it's ready to cook.",hi:"रातभर भिगोकर, फिर एक-दो दिन नम और ढककर रखकर मोठ अंकुरित करें — छोटे सफ़ेद अंकुर आने का मतलब है यह पकाने के लिए तैयार है।"}},{id:"kulthi",wiki:"Horse_gram",emoji:"🟠",name:{en:"Kulthi (Horse Gram)",hi:"कुलथी"},desc:{en:"A small, reddish-brown lentil with a strong, earthy flavor, traditionally valued as a warming winter dal in South India.",hi:"छोटी, लाल-भूरी दाल जिसका स्वाद तीखा और मिट्टी जैसा होता है, परंपरागत रूप से दक्षिण भारत में सर्दी की गर्म तासीर वाली दाल के रूप में मूल्यवान।"},origin:{en:"Grown in the drier, hilly parts of Karnataka, Tamil Nadu, and Andhra Pradesh, where few other legumes thrive.",hi:"कर्नाटक, तमिलनाडु और आंध्र प्रदेश के सूखे, पहाड़ी हिस्सों में उगाई जाती है, जहाँ बहुत कम अन्य फलियाँ पनपती हैं।"},benefits:{en:"Traditionally considered warming in Ayurveda and reached for during colder months and after physical exertion.",hi:"आयुर्वेद में परंपरागत रूप से गर्म तासीर वाली मानी जाती है और सर्दियों तथा शारीरिक मेहनत के बाद अपनाई जाती है।"},uses:{en:"Kulthi rasam, kulthi curry, and a warming kulthi soup often given in winter in parts of South India.",hi:"कुलथी रसम, कुलथी करी, और दक्षिण भारत के कुछ हिस्सों में सर्दियों में दिया जाने वाला गर्म कुलथी सूप।"},tip:{en:"Roast kulthi lightly before cooking — this mellows its strong raw flavor and makes rasam or soup taste rounder.",hi:"पकाने से पहले कुलथी को हल्का भून लें — इससे इसका तीखा कच्चा स्वाद कम होता है और रसम या सूप का स्वाद बेहतर लगता है।"}},{id:"valdal",wiki:"Lablab_purpureus",emoji:"🟢",name:{en:"Val Dal (Lima / Butter Beans)",hi:"वाल दाल (सेम)"},desc:{en:"Flat, broad, buttery-textured beans found fresh or split, giving a mild, creamy bite to winter curries.",hi:"चपटी, चौड़ी, मक्खन जैसी बनावट वाली फलियाँ जो ताज़ी या बँटी मिलती हैं, सर्दियों की करी को हल्का, मलाईदार स्वाद देती हैं।"},origin:{en:"Common across Gujarat and Maharashtra as a fresh winter vegetable and dried pulse.",hi:"गुजरात और महाराष्ट्र में सर्दियों की ताज़ी सब्ज़ी और सूखी दाल दोनों रूप में आम।"},benefits:{en:"A good plant protein source, and being lower in the strong flavors of some other lentils, it pairs easily into mixed vegetable dishes.",hi:"अच्छा पौधा-प्रोटीन स्रोत, और कुछ अन्य दालों के तीखे स्वाद की तुलना में हल्की होने से मिश्रित सब्ज़ी व्यंजनों में आसानी से घुल जाती है।"},uses:{en:"Val dal curry, undhiyu (mixed with other winter vegetables), and fresh val beans stir-fried simply with spices.",hi:"वाल दाल की सब्ज़ी, उंधियू (अन्य सर्दी की सब्ज़ियों के साथ मिली), और ताज़ी वाल फलियाँ मसालों के साथ हल्की भुनी।"},tip:{en:"Dried val dal benefits from a longer soak, ideally overnight, since its flatter shape can otherwise cook unevenly.",hi:"सूखी वाल दाल को लंबे समय, अच्छे से रातभर भिगोना फ़ायदेमंद है, वरना इसका चपटा आकार असमान रूप से पक सकता है।"}}],VEGETABLES=[{id:"bhindi",wiki:"Okra",emoji:"🟢",name:{en:"Bhindi (Okra / Lady Finger)",hi:"भिंडी"},desc:{en:"A ridged green pod that turns sticky if over-handled but crisps up beautifully when fried dry and fast.",hi:"धारीदार हरी फली जो ज़्यादा छूने पर चिपचिपी हो जाती है पर तेज़ आँच पर सूखी तली जाने पर बेहतरीन कुरकुरी बनती है।"},origin:{en:"Grown across nearly every Indian state; a warm-season crop that thrives through summer and monsoon.",hi:"लगभग हर भारतीय राज्य में उगाई जाती है; गर्मी और मानसून में पनपने वाली गर्म-मौसम की फ़सल।"},benefits:{en:"A good source of fiber and Vitamin C, and traditionally considered gentle on digestion when cooked dry rather than in heavy gravy.",hi:"फ़ाइबर और विटामिन C का अच्छा स्रोत, और भारी ग्रेवी की बजाय सूखी पकाने पर परंपरागत रूप से पाचन के लिए हल्की मानी जाती है।"},uses:{en:"Bhindi masala, kurkuri (crispy fried) bhindi, and stuffed bharwan bhindi.",hi:"भिंडी मसाला, कुरकुरी भिंडी, और भरवां भिंडी।"},tip:{en:"Dry the washed bhindi completely before cutting, and avoid covering the pan while frying — trapped moisture is what causes the sliminess.",hi:"धोई भिंडी को काटने से पहले पूरी तरह सुखाएँ, और तलते समय पैन ढँकें नहीं — बंद भाप से ही चिपचिपापन आता है।"}},{id:"baingan",wiki:"Eggplant",emoji:"🍆",name:{en:"Baingan (Eggplant / Brinjal)",hi:"बैंगन"},desc:{en:"A spongy, mild vegetable that soaks up whatever spice or smoke it is cooked with — equally at home mashed or fried.",hi:"हल्का, स्पंज जैसा सब्ज़ी जो जिन मसालों या धुएँ में पकती है उन्हें सोख लेती है — मसलकर या तलकर दोनों तरह बढ़िया।"},origin:{en:"Grown throughout India in countless regional varieties — long purple, round, and small white types among them.",hi:"भारत भर में कई क्षेत्रीय किस्मों में उगाई जाती है — लंबी बैंगनी, गोल और छोटी सफ़ेद किस्मों समेत।"},benefits:{en:"Low in calories and a source of fiber and antioxidants, particularly in the skin, which is why most recipes keep it on.",hi:"कैलोरी में कम और फ़ाइबर-एंटीऑक्सीडेंट का स्रोत, खासकर छिलके में, इसीलिए ज़्यादातर व्यंजनों में छिलका रखा जाता है।"},uses:{en:"Baingan bharta (smoked and mashed), baingan ka bharwan (stuffed), and thin-sliced fried baingan.",hi:"बैंगन भर्ता (धुआँ देकर मसला हुआ), भरवां बैंगन, और पतले कटे तले बैंगन।"},tip:{en:"For bharta, char the whole eggplant directly over an open flame until the skin blisters black — this smokiness is what defines the dish.",hi:"भर्ते के लिए साबुत बैंगन को सीधे खुली आँच पर तब तक भूनें जब तक छिलका काला न पड़ जाए — यही धुआँपन व्यंजन की पहचान है।"}},{id:"lauki",wiki:"Bottle_gourd",emoji:"🥒",name:{en:"Lauki (Bottle Gourd)",hi:"लौकी"},desc:{en:"A pale green, watery gourd with a very mild flavor, valued in Indian kitchens as a light, easy-to-digest vegetable.",hi:"हल्के हरे रंग की, पानी से भरी लौकी जिसका स्वाद बहुत हल्का होता है, भारतीय रसोई में हल्की, आसानी से पचने वाली सब्ज़ी के रूप में मूल्यवान।"},origin:{en:"Grown across nearly all of India as a fast-growing vine crop, especially in the warmer months.",hi:"लगभग पूरे भारत में तेज़ी से बढ़ने वाली बेल की फ़सल के रूप में उगाई जाती है, विशेष रूप से गर्म महीनों में।"},benefits:{en:"High water content and low calories make it a common choice during illness recovery or for a lighter meal.",hi:"ज़्यादा पानी और कम कैलोरी इसे बीमारी से स्वास्थ्य-लाभ या हल्के भोजन के दौरान आम पसंद बनाती है।"},uses:{en:"Lauki ki sabzi, lauki kofta (fried dumplings in gravy), and lauki ka raita.",hi:"लौकी की सब्ज़ी, लौकी कोफ्ता (ग्रेवी में तले हुए), और लौकी का रायता।"},tip:{en:"Taste a small raw piece before cooking — occasionally lauki turns bitter, and cooking a bitter one won't fix the flavor.",hi:"पकाने से पहले एक छोटा कच्चा टुकड़ा चख लें — कभी-कभी लौकी कड़वी हो जाती है, और कड़वी लौकी पकाने से स्वाद ठीक नहीं होता।"}},{id:"gobi",wiki:"Cauliflower",emoji:"🥦",name:{en:"Gobi (Cauliflower)",hi:"गोभी (फूलगोभी)"},desc:{en:"Firm white florets that turn golden and slightly nutty when roasted or fried, one of the most versatile winter vegetables.",hi:"सख़्त सफ़ेद फूल जो भुनने या तलने पर सुनहरे और हल्के मेवे जैसे हो जाते हैं, सर्दियों की सबसे बहुमुखी सब्ज़ियों में से एक।"},origin:{en:"A winter crop grown across North India — Uttar Pradesh, Bihar, and West Bengal among the largest producers.",hi:"उत्तर भारत में उगाई जाने वाली सर्दी की फ़सल — उत्तर प्रदेश, बिहार और पश्चिम बंगाल सबसे बड़े उत्पादकों में से हैं।"},benefits:{en:"A good source of Vitamin C and fiber, and popular as a lighter alternative to potato in many home dishes.",hi:"विटामिन C और फ़ाइबर का अच्छा स्रोत, और कई घरेलू व्यंजनों में आलू के हल्के विकल्प के रूप में लोकप्रिय।"},uses:{en:"Aloo gobi, gobi manchurian, gobi paratha, and crisp-fried gobi 65.",hi:"आलू गोभी, गोभी मंचूरियन, गोभी पराठा, और कुरकुरी तली गोभी 65।"},tip:{en:"Soak cut florets briefly in warm salted water before cooking — it helps flush out any hidden insects and cleans the tight crevices.",hi:"पकाने से पहले कटे फूलों को गुनगुने नमकीन पानी में थोड़ी देर भिगोएँ — इससे छिपे कीड़े निकल जाते हैं और दरारें साफ़ हो जाती हैं।"}},{id:"palak",wiki:"Spinach",emoji:"🥬",name:{en:"Palak (Spinach)",hi:"पालक"},desc:{en:"Dark, tender leafy greens that wilt down quickly and cook into everything from silky purées to hearty sautés.",hi:"गहरी, नरम पत्तेदार सब्ज़ी जो जल्दी सिकुड़ जाती है और रेशमी प्यूरी से लेकर भरपूर भुनी सब्ज़ी तक हर चीज़ में पकती है।"},origin:{en:"Grown throughout North India in the cooler months, when the leaves are at their most tender.",hi:"उत्तर भारत में ठंडे महीनों में उगाई जाती है, जब पत्तियाँ सबसे नरम होती हैं।"},benefits:{en:"Rich in iron and folate, and one of the most commonly recommended leafy greens in Indian home cooking for building strength.",hi:"आयरन और फोलेट से भरपूर, और भारतीय घरेलू खाने में ताक़त बढ़ाने के लिए सबसे ज़्यादा सुझाई जाने वाली पत्तेदार सब्ज़ियों में से एक।"},uses:{en:"Palak paneer, saag, palak dal, and blended into parathas for color and nutrition.",hi:"पालक पनीर, साग, पालक दाल, और रंग व पोषण के लिए पराठों में मिलाई जाती है।"},tip:{en:"Blanch spinach in boiling water for just 1-2 minutes and shock it in cold water immediately — this keeps the color a vivid green instead of dull olive.",hi:"पालक को उबलते पानी में सिर्फ़ 1-2 मिनट उबालें और तुरंत ठंडे पानी में डालें — इससे रंग गहरा हरा रहता है, फीका जैतूनी नहीं होता।"}},{id:"aloo",wiki:"Potato",emoji:"🥔",name:{en:"Aloo (Potato)",hi:"आलू"},desc:{en:"India's most universally loved vegetable, mild and starchy enough to blend into almost any regional spice profile.",hi:"भारत की सबसे सर्वव्यापी पसंदीदा सब्ज़ी, इतनी हल्की और स्टार्चयुक्त कि लगभग किसी भी क्षेत्रीय मसाले में घुल जाती है।"},origin:{en:"Grown across Uttar Pradesh, West Bengal, and Punjab — India is one of the world's largest potato producers.",hi:"उत्तर प्रदेश, पश्चिम बंगाल और पंजाब में उगाया जाता है — भारत दुनिया के सबसे बड़े आलू उत्पादकों में से एक।"},benefits:{en:"A good source of energy-giving carbohydrates and potassium, though best balanced with vegetables and lentils in a full meal.",hi:"ऊर्जा देने वाले कार्बोहाइड्रेट और पोटेशियम का अच्छा स्रोत, हालांकि पूरे भोजन में सब्ज़ियों और दालों के साथ संतुलित करना बेहतर है।"},uses:{en:"Aloo gobi, aloo paratha, dum aloo, and as the base of countless street food snacks like tikki and vada pav.",hi:"आलू गोभी, आलू पराठा, दम आलू, और टिक्की व वड़ा पाव जैसे अनगिनत स्ट्रीट फूड नाश्तों का आधार।"},tip:{en:"For dum aloo, prick small potatoes all over before frying — this lets the spices penetrate deeper once they go into the gravy.",hi:"दम आलू के लिए तलने से पहले छोटे आलुओं में हर तरफ़ काँटे से छेद करें — इससे ग्रेवी में जाने पर मसाले गहराई तक जाते हैं।"}},{id:"gajar",wiki:"Carrot",emoji:"🥕",name:{en:"Gajar (Carrot)",hi:"गाजर"},desc:{en:"Sweet, crunchy roots that turn deeply rich when slow-cooked with milk and ghee into India's favorite winter dessert.",hi:"मीठी, कुरकुरी जड़ें जो दूध और घी के साथ धीमी आँच पर पकने पर भारत की पसंदीदा सर्दियों की मिठाई में बदल जाती हैं।"},origin:{en:"North Indian red carrots, grown in Punjab and Delhi's surrounding belt in winter, are prized for their deep color and sweetness.",hi:"उत्तर भारतीय लाल गाजर, पंजाब और दिल्ली के आसपास सर्दियों में उगाई जाती हैं, अपने गहरे रंग और मिठास के लिए मूल्यवान।"},benefits:{en:"Rich in beta-carotene, which the body converts to Vitamin A, traditionally linked to eye health.",hi:"बीटा-कैरोटीन से भरपूर, जिसे शरीर विटामिन A में बदलता है, परंपरागत रूप से आँखों के स्वास्थ्य से जुड़ा।"},uses:{en:"Gajar ka halwa, gajar-matar sabzi, and grated raw into salads and raita.",hi:"गाजर का हलवा, गाजर-मटर की सब्ज़ी, और कद्दूकस कर सलाद व रायते में।"},tip:{en:"The deep red winter carrots make a noticeably better, sweeter halwa than the paler orange ones available year-round.",hi:"सर्दियों की गहरी लाल गाजर साल भर मिलने वाली हल्की नारंगी गाजर से स्पष्ट रूप से बेहतर, मीठा हलवा बनाती है।"}},{id:"matar",wiki:"Pea",emoji:"🟢",name:{en:"Matar (Green Peas)",hi:"मटर"},desc:{en:"Sweet green peas, at their best fresh off the pod in winter, adding pops of color and sweetness to countless dishes.",hi:"मीठी हरी मटर, सर्दियों में फली से ताज़ी निकाली जाने पर सबसे बेहतरीन, अनगिनत व्यंजनों में रंग और मिठास जोड़ती है।"},origin:{en:"A winter crop grown widely across North India, with fresh matar season stretching roughly November through February.",hi:"उत्तर भारत में व्यापक रूप से उगाई जाने वाली सर्दी की फ़सल, ताज़ी मटर का मौसम लगभग नवंबर से फ़रवरी तक रहता है।"},benefits:{en:"A good plant source of protein and fiber for a vegetable, and a favorite way to add nutrition to rice and gravies.",hi:"सब्ज़ी के लिहाज़ से प्रोटीन और फ़ाइबर का अच्छा पौधा-स्रोत, और चावल व ग्रेवी में पोषण जोड़ने का पसंदीदा तरीका।"},uses:{en:"Matar paneer, aloo matar, matar pulao, and fresh matar kachori.",hi:"मटर पनीर, आलू मटर, मटर पुलाव, और ताज़ी मटर की कचौरी।"},tip:{en:"Fresh winter matar needs almost no cooking time — add it near the end of a dish to keep it sweet and bright green rather than dull.",hi:"ताज़ी सर्दियों की मटर को पकने में लगभग समय नहीं लगता — व्यंजन के अंत में डालें ताकि यह मीठी और चमकदार हरी रहे, फीकी नहीं।"}},{id:"kaddu",wiki:"Pumpkin",emoji:"🎃",name:{en:"Kaddu (Pumpkin)",hi:"कद्दू"},desc:{en:"A sweet, orange squash cooked down into a soft, lightly spiced sabzi, popular in both everyday and festive meals.",hi:"मीठा, नारंगी कद्दू जो नरम, हल्के मसाले वाली सब्ज़ी में पकाया जाता है, रोज़ाना और त्योहारी दोनों भोजनों में लोकप्रिय।"},origin:{en:"Grown across most of India, with several regional varieties differing in sweetness and texture.",hi:"भारत के अधिकांश हिस्सों में उगाया जाता है, कई क्षेत्रीय किस्में मिठास और बनावट में अलग होती हैं।"},benefits:{en:"Rich in beta-carotene and fiber, and its natural sweetness means many kaddu dishes need very little added sugar.",hi:"बीटा-कैरोटीन और फ़ाइबर से भरपूर, और इसकी प्राकृतिक मिठास का मतलब है कि ज़्यादातर कद्दू व्यंजनों में बहुत कम चीनी की ज़रूरत होती है।"},uses:{en:"Kaddu ki sabzi with panch phoron, kaddu ka halwa, and kaddu ki kheer.",hi:"पंचफोरन के साथ कद्दू की सब्ज़ी, कद्दू का हलवा, और कद्दू की खीर।"},tip:{en:"A touch of jaggery or a squeeze of lemon at the end balances kaddu's natural sweetness against the savory spices in the sabzi.",hi:"अंत में थोड़ा गुड़ या नींबू की कुछ बूँदें कद्दू की प्राकृतिक मिठास को सब्ज़ी के नमकीन मसालों के साथ संतुलित करती हैं।"}},{id:"tinda",wiki:"Praecitrullus_fistulosus",emoji:"🟢",name:{en:"Tinda (Apple Gourd)",hi:"टिंडा"},desc:{en:"A small, round, pale green gourd with a mild flavor similar to a cross between squash and cucumber.",hi:"छोटा, गोल, हल्के हरे रंग का कद्दू जिसका स्वाद तोरई और खीरे के बीच जैसा हल्का होता है।"},origin:{en:"Grown widely in North India, especially Punjab, Haryana, and Rajasthan, through the summer months.",hi:"उत्तर भारत में, विशेष रूप से पंजाब, हरियाणा और राजस्थान में, गर्मी के महीनों में व्यापक रूप से उगाया जाता है।"},benefits:{en:"Low in calories and easy to digest, often grouped with lauki and other gourds as a light summer vegetable.",hi:"कैलोरी में कम और आसानी से पचने वाला, अक्सर लौकी और अन्य कद्दू सब्ज़ियों के साथ गर्मियों की हल्की सब्ज़ी माना जाता है।"},uses:{en:"Tinde ki sabzi cooked simply with onion-tomato masala, and tinda bharwan (stuffed).",hi:"प्याज़-टमाटर मसाले के साथ सादगी से पकी टिंडे की सब्ज़ी, और भरवां टिंडा।"},tip:{en:"Choose smaller, firmer tinda — larger ones tend to have tougher skin and more seeds inside.",hi:"छोटे, सख़्त टिंडे चुनें — बड़े टिंडों का छिलका ज़्यादा सख़्त और अंदर बीज ज़्यादा होते हैं।"}}],NUTS_DRYFRUITS=[{id:"kaju",wiki:"Cashew",emoji:"🥜",name:{en:"Kaju (Cashew)",hi:"काजू"},desc:{en:"A creamy, mildly sweet nut that grinds into a smooth paste, used to thicken and enrich rich North Indian gravies.",hi:"मलाईदार, हल्का मीठा मेवा जो चिकने पेस्ट में पिसता है, समृद्ध उत्तर भारतीय ग्रेवी को गाढ़ा और भरपूर बनाने के लिए उपयोग होता है।"},origin:{en:"India grows and processes a large share of the world's cashews, with Kerala, Goa, and Maharashtra as major hubs.",hi:"भारत दुनिया के काजू का बड़ा हिस्सा उगाता और प्रसंस्कृत करता है, केरल, गोवा और महाराष्ट्र मुख्य केंद्र हैं।"},benefits:{en:"A good source of healthy fats and minerals like magnesium, though calorie-dense so typically used in moderation.",hi:"स्वस्थ वसा और मैग्नीशियम जैसे खनिजों का अच्छा स्रोत, हालांकि कैलोरी में भारी होने से आमतौर पर सीमित मात्रा में उपयोग होता है।"},uses:{en:"Ground into paste for korma and shahi gravies, whole in biryani and kheer, and roasted as a snack.",hi:"कोरमा और शाही ग्रेवी के लिए पेस्ट में पिसा, बिरयानी-खीर में साबुत, और नाश्ते के रूप में भुना जाता है।"},tip:{en:"Soak cashews in warm water for 15-20 minutes before blending — this gives a much smoother, lump-free paste for gravies.",hi:"पीसने से पहले काजू को गुनगुने पानी में 15-20 मिनट भिगोएँ — इससे ग्रेवी के लिए ज़्यादा चिकना, बिना गुठली का पेस्ट बनता है।"}},{id:"badam",wiki:"Almond",emoji:"🌰",name:{en:"Badam (Almond)",hi:"बादाम"},desc:{en:"A firm, mildly sweet nut, often soaked and peeled before use — one of the most traditional morning foods in Indian homes.",hi:"सख़्त, हल्का मीठा मेवा, अक्सर उपयोग से पहले भिगोकर छीला जाता है — भारतीय घरों के सबसे पारंपरिक सुबह के खानों में से एक।"},origin:{en:"Not widely grown in India (Kashmir has a small crop); most almonds consumed are imported, largely from the US and the Middle East.",hi:"भारत में व्यापक रूप से नहीं उगाया जाता (कश्मीर में थोड़ी फ़सल); ज़्यादातर बादाम आयातित होते हैं, मुख्यतः अमेरिका और मध्य-पूर्व से।"},benefits:{en:"A good source of Vitamin E and healthy fats; soaked almonds are traditionally believed in Ayurveda to be easier to digest and better for the brain.",hi:"विटामिन E और स्वस्थ वसा का अच्छा स्रोत; भिगोए बादाम आयुर्वेद में परंपरागत रूप से पचाने में आसान और दिमाग़ के लिए बेहतर माने जाते हैं।"},uses:{en:"Eaten soaked and peeled each morning, ground into badam milk, and slivered as a garnish for kheer and halwa.",hi:"हर सुबह भिगोकर छीलकर खाया जाता है, बादाम दूध में पिसा जाता है, और खीर-हलवे पर कतरन के रूप में सजाया जाता है।"},tip:{en:"Soak almonds overnight in water — the skin then peels off easily with a light pinch, no knife needed.",hi:"बादाम को रातभर पानी में भिगोएँ — फिर हल्के दबाव से छिलका आसानी से उतर जाता है, चाकू की ज़रूरत नहीं।"}},{id:"pista",wiki:"Pistachio",emoji:"🟢",name:{en:"Pista (Pistachio)",hi:"पिस्ता"},desc:{en:"A vividly green nut with a distinctive flavor, prized as much for its color as its taste in festive Indian sweets.",hi:"चमकदार हरे रंग का मेवा जिसका स्वाद खास होता है, त्योहारी भारतीय मिठाइयों में स्वाद जितना ही अपने रंग के लिए भी मूल्यवान।"},origin:{en:"Mostly imported into India, primarily from Iran and the United States, though a small crop grows in parts of Jammu & Kashmir.",hi:"ज़्यादातर भारत में आयातित, मुख्यतः ईरान और अमेरिका से, हालांकि जम्मू-कश्मीर के कुछ हिस्सों में थोड़ी फ़सल उगती है।"},benefits:{en:"A good source of protein and antioxidants among nuts, and its green color comes from natural plant pigments.",hi:"मेवों में प्रोटीन और एंटीऑक्सीडेंट का अच्छा स्रोत, और इसका हरा रंग प्राकृतिक पौधे-वर्णक से आता है।"},uses:{en:"Slivered as a garnish on kulfi and kheer, ground into pista barfi, and mixed into festive dry fruit mixes.",hi:"कुल्फी और खीर पर कतरन के रूप में, पिस्ता बर्फी में पिसा हुआ, और त्योहारी मेवा मिश्रण में मिलाया जाता है।"},tip:{en:"Blanch pistachios briefly in hot water to loosen the thin skin before slivering — this keeps the green color from being dulled by the papery skin.",hi:"कतरन से पहले पतले छिलके को ढीला करने के लिए पिस्ते को गरम पानी में थोड़ी देर डालें — इससे कागज़ जैसे छिलके से हरा रंग फीका नहीं पड़ता।"}},{id:"kishmish",wiki:"Raisin",emoji:"🍇",name:{en:"Kishmish (Raisins)",hi:"किशमिश"},desc:{en:"Sun-dried grapes that turn syrupy-sweet and plump when soaked, adding little bursts of sweetness to savory rice dishes.",hi:"धूप में सुखाए अंगूर जो भिगोने पर मीठे रस से भर जाते हैं, नमकीन चावल व्यंजनों में मिठास के छोटे-छोटे फोड़े जोड़ते हैं।"},origin:{en:"Produced mainly in Maharashtra's Nashik and Sangli regions, from the same grape-growing belts known for Indian wine.",hi:"मुख्य रूप से महाराष्ट्र के नासिक और सांगली क्षेत्रों में उत्पादित, उन्हीं अंगूर-उगाने वाले क्षेत्रों से जो भारतीय वाइन के लिए जाने जाते हैं।"},benefits:{en:"A concentrated source of natural sugars and iron, traditionally soaked in water overnight and the water drunk for its believed iron benefits.",hi:"प्राकृतिक शर्करा और आयरन का सघन स्रोत, परंपरागत रूप से रातभर पानी में भिगोकर, आयरन लाभ के लिए वह पानी भी पिया जाता है।"},uses:{en:"Studded through pulao and biryani, folded into kheer, and part of nearly every festive dry fruit mix.",hi:"पुलाव और बिरयानी में जड़ी हुई, खीर में मिली हुई, और लगभग हर त्योहारी मेवा मिश्रण का हिस्सा।"},tip:{en:"Frying raisins briefly in ghee until they puff up brings out a much deeper sweetness than adding them in raw.",hi:"किशमिश को घी में तब तक हल्का तलें जब तक वे फूल न जाएँ — इससे कच्ची डालने से कहीं गहरी मिठास आती है।"}},{id:"khajoor",wiki:"Date_palm",emoji:"🌴",name:{en:"Khajoor (Dates)",hi:"खजूर"},desc:{en:"A naturally sweet, chewy fruit used both as a healthier sugar substitute and as a beloved snack on its own.",hi:"स्वाभाविक रूप से मीठा, चबाने योग्य फल जो स्वस्थ चीनी विकल्प के रूप में और खुद भी प्रिय नाश्ते के रूप में उपयोग होता है।"},origin:{en:"Grown in the drier parts of Rajasthan and Gujarat, though much of what's consumed in India is imported from the Middle East.",hi:"राजस्थान और गुजरात के सूखे हिस्सों में उगाया जाता है, हालांकि भारत में खाया जाने वाला ज़्यादातर मध्य-पूर्व से आयातित है।"},benefits:{en:"A concentrated source of natural energy and fiber, and often used as a natural sweetener in place of refined sugar.",hi:"प्राकृतिक ऊर्जा और फ़ाइबर का सघन स्रोत, और अक्सर परिष्कृत चीनी की जगह प्राकृतिक मिठास के रूप में उपयोग होता है।"},uses:{en:"Blended into date-sweetened kheer and ladoos, stuffed with nuts as a snack, and part of dry fruit mixes.",hi:"खजूर-मीठी खीर और लड्डू में मिलाया जाता है, मेवे भरकर नाश्ते के रूप में, और मेवा मिश्रण का हिस्सा।"},tip:{en:"Deseeded dates blended with a splash of warm water make a smooth natural sweetener that works well in place of sugar in many desserts.",hi:"बीज निकाले खजूर को थोड़े गरम पानी के साथ पीसना कई मिठाइयों में चीनी की जगह अच्छा काम करने वाला चिकना प्राकृतिक मीठा बनाता है।"}},{id:"akhrot",wiki:"Walnut",emoji:"🌰",name:{en:"Akhrot (Walnut)",hi:"अखरोट"},desc:{en:"A wrinkled, brain-shaped nut with a slightly bitter edge, used both as a snack and folded into festive sweets.",hi:"झुर्रीदार, दिमाग़ के आकार का मेवा जिसका स्वाद हल्का कड़वा होता है, नाश्ते और त्योहारी मिठाइयों दोनों में उपयोग होता है।"},origin:{en:"Grown mainly in the cooler valleys of Jammu & Kashmir and Himachal Pradesh.",hi:"मुख्य रूप से जम्मू-कश्मीर और हिमाचल प्रदेश की ठंडी घाटियों में उगाया जाता है।"},benefits:{en:"One of the few nuts rich in plant-based omega-3 fatty acids, and traditionally associated with brain health because of its shape and nutrient profile.",hi:"पौधा-आधारित ओमेगा-3 फैटी एसिड से भरपूर कुछ मेवों में से एक, और अपने आकार व पोषण के कारण परंपरागत रूप से दिमाग़ के स्वास्थ्य से जुड़ा।"},uses:{en:"Akhrot ki chutney in Kashmiri cuisine, chopped into halwa and cakes, and eaten plain as a snack.",hi:"कश्मीरी व्यंजनों में अखरोट की चटनी, हलवे और केक में कटा हुआ, और सादा नाश्ते के रूप में खाया जाता है।"},tip:{en:"Toast walnuts briefly in a dry pan before using in desserts — it removes any lingering bitterness and deepens the flavor.",hi:"मिठाइयों में उपयोग से पहले अखरोट को सूखे तवे पर हल्का भून लें — इससे बचा-खुचा कड़वापन दूर होता है और स्वाद गहरा होता है।"}},{id:"chironji",wiki:"Buchanania_cochinchinensis",emoji:"🟤",name:{en:"Chironji (Charoli)",hi:"चिरौंजी"},desc:{en:"Tiny, lentil-sized seeds with a flavor between almond and pistachio, a lesser-known but classic Indian sweet-making ingredient.",hi:"दाल के आकार के छोटे बीज जिनका स्वाद बादाम और पिस्ते के बीच होता है, कम जाना-पहचाना पर मिठाई बनाने का पारंपरिक भारतीय घटक।"},origin:{en:"Collected from wild trees found across central India — Madhya Pradesh, Chhattisgarh, and parts of Maharashtra.",hi:"मध्य भारत में जंगली पेड़ों से इकट्ठी की जाती है — मध्य प्रदेश, छत्तीसगढ़ और महाराष्ट्र के कुछ हिस्सों में।"},benefits:{en:"A good source of healthy fats similar to other nuts, traditionally used in small quantities as a garnish rather than a main ingredient.",hi:"अन्य मेवों जैसा स्वस्थ वसा का अच्छा स्रोत, परंपरागत रूप से मुख्य सामग्री की बजाय थोड़ी मात्रा में सजावट के रूप में उपयोग होता है।"},uses:{en:"Sprinkled over kheer and shrikhand, and ground into some traditional festive sweet fillings.",hi:"खीर और श्रीखंड पर छिड़का जाता है, और कुछ पारंपरिक त्योहारी मिठाइयों की भरावन में पिसा जाता है।"},tip:{en:"Toast chironji lightly in a dry pan before use — it brings out a nuttier flavor that plain raw seeds lack.",hi:"उपयोग से पहले चिरौंजी को सूखे तवे पर हल्का भून लें — इससे कच्चे बीजों में न मिलने वाला मेवे जैसा स्वाद आता है।"}},{id:"anjeer",wiki:"Common_fig",emoji:"🟣",name:{en:"Anjeer (Fig)",hi:"अंजीर"},desc:{en:"A soft, seed-flecked dried fruit with a mellow sweetness, often recommended in Ayurveda as a gentle, nourishing food.",hi:"नरम, बीज जड़ित सूखा फल जिसकी मिठास हल्की होती है, आयुर्वेद में अक्सर हल्के, पौष्टिक भोजन के रूप में सुझाया जाता है।"},origin:{en:"Grown domestically in Maharashtra's Pune region, alongside significant imports from Afghanistan and Turkey.",hi:"महाराष्ट्र के पुणे क्षेत्र में स्वदेशी रूप से उगाया जाता है, साथ ही अफ़ग़ानिस्तान और तुर्की से भी काफ़ी आयातित होता है।"},benefits:{en:"A good source of fiber and natural sugars, and traditionally soaked overnight and eaten to support digestion.",hi:"फ़ाइबर और प्राकृतिक शर्करा का अच्छा स्रोत, और परंपरागत रूप से रातभर भिगोकर पाचन के लिए खाया जाता है।"},uses:{en:"Eaten soaked as a daily snack, blended into anjeer barfi, and chopped into festive dry fruit mixes.",hi:"रोज़ाना नाश्ते के रूप में भिगोकर खाया जाता है, अंजीर बर्फी में पिसा जाता है, और त्योहारी मेवा मिश्रण में कटा हुआ मिलाया जाता है।"},tip:{en:"Soak dried figs in warm water for about 30 minutes before eating — this softens them and makes their natural sweetness more pronounced.",hi:"सूखे अंजीर को खाने से पहले लगभग 30 मिनट गुनगुने पानी में भिगोएँ — इससे वे नरम होते हैं और प्राकृतिक मिठास ज़्यादा उभरती है।"}}],DAIRY=[{id:"ghee",wiki:"Ghee",emoji:"🧈",name:{en:"Ghee (Clarified Butter)",hi:"घी"},desc:{en:"Butter simmered until the milk solids separate and brown, leaving behind a nutty, richly aromatic pure fat.",hi:"मक्खन को तब तक उबाला जाता है जब तक दूध के ठोस अलग होकर सुनहरे न हो जाएँ, पीछे मेवे जैसी खुशबूदार शुद्ध चर्बी रह जाती है।"},origin:{en:"Made in homes across India for centuries, traditionally from cow's milk butter, with regional variations in the churning method.",hi:"सदियों से भारतीय घरों में बनाया जाता है, परंपरागत रूप से गाय के दूध के मक्खन से, मथने की विधि में क्षेत्रीय भिन्नताओं के साथ।"},benefits:{en:"A source of fat-soluble vitamins, and in Ayurveda considered one of the most nourishing and easily digestible fats.",hi:"वसा में घुलनशील विटामिनों का स्रोत, और आयुर्वेद में सबसे पौष्टिक और आसानी से पचने वाली चर्बी में से एक माना जाता है।"},uses:{en:"Used for tempering, frying puris, finishing dal, and drizzled over hot rotis and khichdi.",hi:"तड़के के लिए, पूरी तलने, दाल में तड़का लगाने, और गरम रोटी-खिचड़ी पर डालने के लिए उपयोग होता है।"},tip:{en:"Cook the butter on low heat and watch closely near the end — ghee can go from perfectly golden to burnt within a minute.",hi:"मक्खन को धीमी आँच पर पकाएँ और अंत में ध्यान से देखें — घी एक मिनट में सुनहरे से जला हुआ हो सकता है।"}},{id:"paneer",wiki:"Paneer",emoji:"🧀",name:{en:"Paneer (Fresh Cheese)",hi:"पनीर"},desc:{en:"Fresh, unaged cheese made by curdling milk, prized for holding its shape when cooked without melting.",hi:"दूध फाड़कर बनाया ताज़ा, बिना पका पनीर, पकाने पर बिना पिघले अपना आकार बनाए रखने के लिए मूल्यवान।"},origin:{en:"Made fresh in homes across North India, especially popular in Punjab and Bengal (where the softer chhena variant is used for sweets).",hi:"उत्तर भारत के घरों में ताज़ा बनाया जाता है, विशेष रूप से पंजाब और बंगाल में लोकप्रिय (जहाँ नरम छेना किस्म मिठाइयों के लिए उपयोग होती है)।"},benefits:{en:"A strong protein and calcium source, and the primary vegetarian protein centerpiece in many North Indian meals.",hi:"मज़बूत प्रोटीन और कैल्शियम स्रोत, और कई उत्तर भारतीय भोजनों में मुख्य शाकाहारी प्रोटीन।"},uses:{en:"Paneer butter masala, palak paneer, paneer tikka, and shahi paneer.",hi:"पनीर बटर मसाला, पालक पनीर, पनीर टिक्का, और शाही पनीर।"},tip:{en:"Curdle boiling milk with lemon juice or vinegar just until it separates, then rinse the curds under cold water to wash away the sour taste before pressing.",hi:"उबलते दूध को नींबू या सिरके से बस उतना फाड़ें जितना ज़रूरी है, फिर दबाने से पहले खट्टापन धोने के लिए ठंडे पानी से धो लें।"}},{id:"khoya",wiki:"Khoa",emoji:"🥛",name:{en:"Khoya (Mawa)",hi:"खोया (मावा)"},desc:{en:"Milk reduced slowly over hours until it thickens into a dense, fudge-like base for many of India's richest sweets.",hi:"दूध को घंटों धीमी आँच पर सुखाकर गाढ़ा, बर्फी जैसा घना आधार बनाया जाता है, भारत की सबसे समृद्ध मिठाइयों के लिए।"},origin:{en:"Made across North India, with Mathura and Agra especially known for producing high-quality khoya for sweets.",hi:"उत्तर भारत में बनाया जाता है, मथुरा और आगरा विशेष रूप से मिठाइयों के लिए उच्च गुणवत्ता वाले खोये के लिए जाने जाते हैं।"},benefits:{en:"Concentrated in milk protein and fat since most of the water has been evaporated out, giving sweets their dense, rich texture.",hi:"ज़्यादातर पानी वाष्पित होने से दूध के प्रोटीन और वसा से सघन, मिठाइयों को घनी, समृद्ध बनावट देता है।"},uses:{en:"The base for gulab jamun, peda, and barfi, and mixed into gajar ka halwa for extra richness.",hi:"गुलाब जामुन, पेड़ा और बर्फी का आधार, और अतिरिक्त समृद्धि के लिए गाजर के हलवे में मिलाया जाता है।"},tip:{en:"Stir constantly and use a heavy-bottomed pan when making khoya at home — it scorches easily once the milk starts to thicken.",hi:"घर पर खोया बनाते समय लगातार चलाते रहें और भारी तले का बर्तन इस्तेमाल करें — दूध गाढ़ा होने पर यह जल्दी जल जाता है।"}},{id:"dahi",wiki:"Dahi_(yogurt)",emoji:"🥣",name:{en:"Dahi (Curd / Yogurt)",hi:"दही"},desc:{en:"Milk set with a live culture into a tangy, thick curd, eaten daily in some form across nearly every Indian household.",hi:"जीवित संवर्धन से जमाया गया दूध, खट्टा, गाढ़ा दही बनता है, लगभग हर भारतीय घर में किसी न किसी रूप में रोज़ाना खाया जाता है।"},origin:{en:"Made fresh daily in most homes by setting warm milk with a spoonful of previous day's curd as starter.",hi:"ज़्यादातर घरों में रोज़ ताज़ा बनाया जाता है, गरम दूध में पिछले दिन के दही का एक चम्मच स्टार्टर के रूप में मिलाकर।"},benefits:{en:"A source of probiotics that supports gut health, and traditionally considered cooling, especially favored in summer.",hi:"प्रोबायोटिक्स का स्रोत जो आंत के स्वास्थ्य में सहायक है, और परंपरागत रूप से ठंडक देने वाला माना जाता है, खासकर गर्मियों में पसंदीदा।"},uses:{en:"Eaten plain with meals, blended into raita and lassi, and used to marinate meat for tandoori dishes.",hi:"भोजन के साथ सादा खाया जाता है, रायते और लस्सी में मिलाया जाता है, और तंदूरी व्यंजनों के लिए मांस मैरिनेट करने में उपयोग होता है।"},tip:{en:"Set curd in a warm spot (like inside an oven with just the light on) — too cold a spot slows fermentation and gives a thin, watery curd.",hi:"दही को गरम जगह जमाएँ (जैसे ओवन के अंदर सिर्फ़ लाइट जलाकर) — ज़्यादा ठंडी जगह किण्वन धीमा करती है और पतला, पानीदार दही बनाती है।"}},{id:"malai",wiki:"Malai",emoji:"🍦",name:{en:"Malai (Cream)",hi:"मलाई"},desc:{en:"The thick, rich layer that forms on top of boiled and cooled milk, skimmed off and prized for its silky richness.",hi:"उबले और ठंडे किए दूध के ऊपर बनी गाढ़ी, समृद्ध परत, जिसे उतारकर उसकी मलाईदार समृद्धि के लिए मूल्यवान माना जाता है।"},origin:{en:"Made fresh in homes by collecting the cream layer daily from boiled milk, especially common with full-fat buffalo milk.",hi:"घरों में उबले दूध से रोज़ाना मलाई की परत इकट्ठा कर ताज़ा बनाई जाती है, विशेष रूप से भरपूर वसा वाले भैंस के दूध के साथ आम।"},benefits:{en:"Rich in fat and calories, traditionally seen as a nourishing, energy-dense food, though used in moderation.",hi:"वसा और कैलोरी में भरपूर, परंपरागत रूप से पौष्टिक, ऊर्जा-सघन भोजन माना जाता है, हालांकि सीमित मात्रा में उपयोग होता है।"},uses:{en:"Malai kofta, malai chicken, mixed into kulfi, and eaten with sugar as a simple sweet treat.",hi:"मलाई कोफ्ता, मलाई चिकन, कुल्फी में मिलाई जाती है, और चीनी के साथ सादी मिठाई के रूप में खाई जाती है।"},tip:{en:"Collect malai daily in a covered container in the fridge — accumulated over a week or two, it becomes enough to churn into fresh homemade butter.",hi:"मलाई रोज़ फ्रिज में ढके बर्तन में इकट्ठा करें — एक-दो हफ़्ते में इकट्ठा होकर यह ताज़ा घर के मक्खन के लिए मथने लायक हो जाती है।"}},{id:"makhan",wiki:"Butter",emoji:"🧈",name:{en:"Makhan (White Butter)",hi:"मक्खन (सफ़ेद मक्खन)"},desc:{en:"Unsalted, unripened butter churned fresh from cream or curd, famously associated with Krishna's childhood in Indian folklore.",hi:"क्रीम या दही से ताज़ा मथा गया बिना नमक, बिना पका मक्खन, भारतीय लोककथाओं में कृष्ण के बचपन से मशहूर रूप से जुड़ा।"},origin:{en:"Churned fresh in homes across North India, traditionally using a wooden bilona (churner) though a blender works today.",hi:"उत्तर भारत के घरों में ताज़ा मथा जाता है, परंपरागत रूप से लकड़ी की बिलौना (मथानी) से, हालांकि आजकल ब्लेंडर भी काम करता है।"},benefits:{en:"A rich source of fat, traditionally eaten fresh on hot rotis or paratha as an everyday indulgence rather than a cooking staple.",hi:"वसा का समृद्ध स्रोत, परंपरागत रूप से गरम रोटी या पराठे पर ताज़ा खाया जाता है, रोज़ाना का स्वाद, पकाने की मुख्य सामग्री नहीं।"},uses:{en:"Spread on bajra roti and makki di roti, the base for making ghee at home, and stirred into dal makhani for richness.",hi:"बाजरे की रोटी और मक्की दी रोटी पर लगाया जाता है, घर पर घी बनाने का आधार, और समृद्धि के लिए दाल मखनी में मिलाया जाता है।"},tip:{en:"Churn chilled malai rather than warm — cold cream separates into butter and buttermilk far more cleanly and quickly.",hi:"गरम की बजाय ठंडी मलाई मथें — ठंडी क्रीम मक्खन और छाछ में कहीं ज़्यादा साफ़ और तेज़ी से अलग होती है।"}},{id:"chaas",wiki:"Chaas",emoji:"🥤",name:{en:"Chaas (Buttermilk)",hi:"छाछ"},desc:{en:"The thin, tangy liquid left after churning butter out of curd, drunk chilled and spiced as a classic summer cooler.",hi:"दही से मक्खन मथने के बाद बचा पतला, खट्टा तरल, ठंडा और मसालेदार पीकर गर्मियों का पारंपरिक शीतल पेय।"},origin:{en:"A byproduct of home butter-making across India, though today often made simply by diluting and whisking curd directly.",hi:"भारत भर में घर के मक्खन बनाने का उपोत्पाद, हालांकि आज अक्सर सीधे दही को पतला कर फेंटकर बनाया जाता है।"},benefits:{en:"Lower in fat than curd itself, and traditionally taken after meals to aid digestion, especially in hot weather.",hi:"दही से वसा में कम, और परंपरागत रूप से पाचन में सहायता के लिए भोजन के बाद लिया जाता है, खासकर गरम मौसम में।"},uses:{en:"Spiced with roasted cumin, mint, and black salt as a drink, and used as the liquid base for kadhi.",hi:"भुने जीरे, पुदीने और काले नमक के साथ मसालेदार पेय के रूप में, और कढ़ी के तरल आधार के रूप में उपयोग होता है।"},tip:{en:"Whisk curd with cold water rather than blending vigorously — too much aeration makes the chaas foamy instead of smooth.",hi:"दही को ज़ोर से ब्लेंड करने की बजाय ठंडे पानी के साथ फेंटें — ज़्यादा हवा मिलने से छाछ चिकनी की बजाय झागदार हो जाती है।"}}],HERBS=[{id:"currypatta",wiki:"Curry_tree",emoji:"🍃",name:{en:"Kadi Patta (Curry Leaves)",hi:"कड़ी पत्ता"},desc:{en:"Small, glossy green leaves that release a distinctive citrusy aroma the moment they hit hot oil.",hi:"छोटी, चमकदार हरी पत्तियाँ जो गरम तेल में डालते ही एक खास नींबू जैसी खुशबू छोड़ती हैं।"},origin:{en:"Grown widely across South India — Tamil Nadu, Karnataka, and Kerala — where it's a near-universal tempering ingredient.",hi:"दक्षिण भारत में व्यापक रूप से उगाई जाती है — तमिलनाडु, कर्नाटक और केरल — जहाँ यह लगभग हर तड़के का हिस्सा है।"},benefits:{en:"Traditionally valued in Ayurveda for digestive support, and used fresh rather than dried whenever possible for maximum aroma.",hi:"आयुर्वेद में परंपरागत रूप से पाचन सहायता के लिए मूल्यवान, और अधिकतम खुशबू के लिए जब भी संभव हो सूखी की बजाय ताज़ी उपयोग होती है।"},uses:{en:"The opening note of nearly every South Indian tadka — sambar, rasam, and coconut chutney all start here.",hi:"लगभग हर दक्षिण भारतीय तड़के की शुरुआती धुन — सांभर, रसम और नारियल चटनी सभी यहीं से शुरू होते हैं।"},tip:{en:"Add curry leaves to hot oil right after the mustard seeds pop — they release their aroma fastest in oil that's already sizzling.",hi:"राई चटकने के तुरंत बाद कड़ी पत्ता गरम तेल में डालें — पहले से चटकते तेल में यह सबसे तेज़ी से खुशबू छोड़ता है।"}},{id:"pudina",wiki:"Mentha",emoji:"🌿",name:{en:"Pudina (Mint)",hi:"पुदीना"},desc:{en:"Bright, cooling leaves with a sharp fresh flavor, equally at home in a summer chutney or a warming winter tea.",hi:"चमकदार, ठंडक देने वाली पत्तियाँ जिनका स्वाद तीखा और ताज़ा होता है, गर्मियों की चटनी और सर्दियों की गर्म चाय दोनों में बराबर बढ़िया।"},origin:{en:"Grown across most of India, thriving especially well in the cooler months near water sources.",hi:"भारत के अधिकांश हिस्सों में उगाई जाती है, विशेष रूप से पानी के स्रोतों के पास ठंडे महीनों में अच्छी तरह पनपती है।"},benefits:{en:"Traditionally used to settle the stomach and freshen breath, and considered a cooling herb well suited to hot weather.",hi:"परंपरागत रूप से पेट को शांत करने और साँस ताज़ा करने के लिए उपयोग होती है, और गरम मौसम के लिए उपयुक्त ठंडी तासीर वाली जड़ी-बूटी मानी जाती है।"},uses:{en:"Pudina chutney, mixed into raita, and steeped for a refreshing mint tea or added to summer coolers.",hi:"पुदीना चटनी, रायते में मिलाया जाता है, और ताज़गी भरी पुदीने की चाय या गर्मियों के शीतल पेय के लिए भिगोया जाता है।"},tip:{en:"Add fresh mint at the very end of cooking or grind it raw into chutney — prolonged cooking dulls both its color and its sharp flavor.",hi:"पकाने के बिल्कुल अंत में ताज़ा पुदीना डालें या कच्चा ही चटनी में पीसें — ज़्यादा पकाने से इसका रंग और तीखा स्वाद दोनों फीके पड़ जाते हैं।"}},{id:"haradhaniya",wiki:"Coriander",emoji:"🌱",name:{en:"Hara Dhaniya (Fresh Coriander / Cilantro)",hi:"हरा धनिया"},desc:{en:"The fresh, feathery leaves of the coriander plant, used as both a flavoring herb and the final garnish on almost every savory dish.",hi:"धनिये के पौधे की ताज़ी, पंखदार पत्तियाँ, स्वाद के लिए जड़ी-बूटी और लगभग हर नमकीन व्यंजन पर आख़िरी सजावट दोनों के रूप में उपयोग होती हैं।"},origin:{en:"Grown throughout India as a fast, easy home-garden crop, sold fresh in every local vegetable market.",hi:"भारत भर में तेज़, आसान घरेलू बगीचे की फ़सल के रूप में उगाई जाती है, हर स्थानीय सब्ज़ी बाज़ार में ताज़ी बिकती है।"},benefits:{en:"A source of Vitamin K and antioxidants, and its bright flavor means dishes need less added salt to taste vibrant.",hi:"विटामिन K और एंटीऑक्सीडेंट का स्रोत, और इसका चटख स्वाद व्यंजनों को जीवंत महसूस कराने के लिए कम नमक की ज़रूरत डालता है।"},uses:{en:"The default garnish for curries and dal, the base of coriander chutney, and blended into marinades.",hi:"करी और दाल के लिए डिफ़ॉल्ट सजावट, धनिया चटनी का आधार, और मैरिनेड में मिलाया जाता है।"},tip:{en:"Store coriander stems-down in a glass of water in the fridge, loosely covered — it stays fresh for over a week instead of wilting in a day or two.",hi:"धनिये को फ्रिज में एक गिलास पानी में डंठल नीचे रखकर, हल्का ढककर रखें — यह एक-दो दिन मुरझाने की बजाय एक हफ़्ते से ज़्यादा ताज़ा रहता है।"}},{id:"kasurimethi",wiki:"Fenugreek",emoji:"🍂",name:{en:"Kasuri Methi (Dried Fenugreek Leaves)",hi:"कसूरी मेथी"},desc:{en:"Sun-dried fenugreek leaves with an intensely aromatic, slightly bitter edge that instantly signals North Indian restaurant-style curry.",hi:"धूप में सुखाई मेथी की पत्तियाँ जिनकी तेज़ खुशबू और हल्की कड़वाहट तुरंत उत्तर भारतीय रेस्टोरेंट-शैली की करी का संकेत देती है।"},origin:{en:"Named after Kasur, a region now in Pakistan, though it is grown and dried widely across North India today.",hi:"पाकिस्तान के अब कासुर क्षेत्र के नाम पर, हालांकि आज उत्तर भारत में व्यापक रूप से उगाई और सुखाई जाती है।"},benefits:{en:"Retains much of fresh fenugreek's traditional digestive reputation in concentrated, shelf-stable dried form.",hi:"ताज़ी मेथी की पारंपरिक पाचन-सहायक प्रतिष्ठा को सघन, टिकाऊ सूखे रूप में काफ़ी हद तक बनाए रखती है।"},uses:{en:"Crushed and sprinkled into butter chicken, paneer butter masala, and most creamy North Indian gravies near the end of cooking.",hi:"बटर चिकन, पनीर बटर मसाला और अधिकांश मलाईदार उत्तर भारतीय ग्रेवी में पकाने के अंत में कुचलकर छिड़का जाता है।"},tip:{en:"Rub the dried leaves between your palms before adding — this releases the aroma far more than dropping the whole leaves in.",hi:"डालने से पहले सूखी पत्तियों को हथेलियों के बीच मसलें — इससे साबुत पत्तियाँ डालने से कहीं ज़्यादा खुशबू निकलती है।"}},{id:"tejpatta",wiki:"Bay_leaf",emoji:"🍃",name:{en:"Tej Patta (Indian Bay Leaf)",hi:"तेज पत्ता"},desc:{en:"A long, fragrant leaf added whole to hot oil at the start of cooking, quietly perfuming rice and gravies without dominating them.",hi:"लंबी, खुशबूदार पत्ती जो पकाने की शुरुआत में गरम तेल में साबुत डाली जाती है, चावल और ग्रेवी को बिना हावी हुए धीरे से खुशबू देती है।"},origin:{en:"Grown in the hilly regions of the Northeast, particularly Sikkim, distinct botanically from the Mediterranean bay leaf.",hi:"पूर्वोत्तर के पहाड़ी क्षेत्रों में उगाई जाती है, विशेष रूप से सिक्किम में, वनस्पति विज्ञान की दृष्टि से भूमध्यसागरीय तेज पत्ते से अलग।"},benefits:{en:"Used more for aroma than nutrition, though traditionally included among the whole spices believed to aid digestion.",hi:"पोषण से ज़्यादा खुशबू के लिए उपयोग होती है, हालांकि परंपरागत रूप से पाचन में सहायक मानी जाने वाली साबुत मसालों में शामिल।"},uses:{en:"A near-universal addition to biryani, pulao, and the whole-spice base of most North Indian gravies.",hi:"बिरयानी, पुलाव और अधिकांश उत्तर भारतीय ग्रेवी के साबुत मसाला आधार में लगभग सार्वभौमिक जोड़।"},tip:{en:"Remove the bay leaf before serving, or warn guests — biting into the tough, fibrous leaf whole is unpleasant even though it's not harmful.",hi:"परोसने से पहले तेज पत्ता निकाल दें, या मेहमानों को बता दें — साबुत सख़्त, रेशेदार पत्ता चबाना अप्रिय है, हालांकि हानिकारक नहीं।"}},{id:"hing",wiki:"Asafoetida",emoji:"🟡",name:{en:"Hing (Asafoetida)",hi:"हींग"},desc:{en:"A pungent resin that smells sharp raw but mellows into a savory, almost garlicky note the moment it hits hot oil.",hi:"तीखा राल जिसकी गंध कच्ची तेज़ होती है पर गरम तेल में डालते ही यह हल्के, लगभग लहसुन जैसे स्वाद में बदल जाती है।"},origin:{en:"Not grown in India — nearly all hing is imported as resin from Afghanistan and Iran, then processed and packaged domestically.",hi:"भारत में नहीं उगाई जाती — लगभग सारी हींग अफ़ग़ानिस्तान और ईरान से राल के रूप में आयातित होती है, फिर देश में प्रसंस्कृत और पैक की जाती है।"},benefits:{en:"Traditionally used to reduce bloating and gas, especially valued in Jain and Marwari cooking, which avoids onion and garlic.",hi:"परंपरागत रूप से पेट फूलने और गैस कम करने के लिए उपयोग होती है, विशेष रूप से जैन और मारवाड़ी खाने में मूल्यवान, जो प्याज़-लहसुन से बचता है।"},uses:{en:"A pinch added to hot oil at the start of tadka for dal, kadhi, and jeera aloo — often replacing onion-garlic flavor.",hi:"दाल, कढ़ी और जीरा आलू के तड़के की शुरुआत में गरम तेल में एक चुटकी डाली जाती है — अक्सर प्याज़-लहसुन के स्वाद की जगह लेती है।"},tip:{en:"A little goes an extremely long way — use just a pinch, since raw hing straight from the tin is far more pungent than it will taste once cooked.",hi:"बहुत थोड़ी ही काफ़ी है — बस एक चुटकी इस्तेमाल करें, क्योंकि डिब्बे से सीधी कच्ची हींग पकने के बाद के स्वाद से कहीं ज़्यादा तीखी होती है।"}},{id:"freshginger",wiki:"Ginger",emoji:"🫚",name:{en:"Adrak (Fresh Ginger)",hi:"अदरक"},desc:{en:"A knobby, fibrous root with a sharp, warming bite, almost always paired with garlic as the flavor base of countless dishes.",hi:"गाँठदार, रेशेदार जड़ जिसका स्वाद तीखा और गर्म होता है, लगभग हमेशा लहसुन के साथ जोड़ी बनाकर अनगिनत व्यंजनों का स्वाद-आधार बनती है।"},origin:{en:"Grown widely across Kerala, Karnataka, and the Northeast, in warm, humid climates suited to root crops.",hi:"केरल, कर्नाटक और पूर्वोत्तर में व्यापक रूप से उगाई जाती है, जड़ वाली फ़सलों के लिए उपयुक्त गरम, आर्द्र जलवायु में।"},benefits:{en:"Traditionally used to ease nausea and aid digestion, and considered warming, especially reached for during colds and cold weather.",hi:"परंपरागत रूप से मतली में राहत और पाचन सहायता के लिए उपयोग होती है, और गर्म तासीर वाली मानी जाती है, खासकर सर्दी और ठंडे मौसम में अपनाई जाती है।"},uses:{en:"Ground into ginger-garlic paste for nearly every curry base, grated fresh into chai, and used in pickles.",hi:"लगभग हर करी के आधार के लिए अदरक-लहसुन पेस्ट में पिसी जाती है, चाय में ताज़ा कद्दूकस की जाती है, और अचार में उपयोग होती है।"},tip:{en:"Freeze whole ginger — it grates easily straight from frozen with no need to peel, since the skin comes right off the grater.",hi:"साबुत अदरक फ्रीज़ करें — जमे हुए से सीधे आसानी से कद्दूकस हो जाती है, छीलने की ज़रूरत नहीं, छिलका कद्दूकस पर ही छूट जाता है।"}},{id:"freshgarlic",wiki:"Garlic",emoji:"🧄",name:{en:"Lahsun (Fresh Garlic)",hi:"लहसुन"},desc:{en:"Pungent cloves that mellow into a deep, savory sweetness when cooked, one half of the ginger-garlic pairing found in most Indian curries.",hi:"तीखी कलियाँ जो पकने पर गहरी, नमकीन मिठास में बदल जाती हैं, अधिकांश भारतीय करी में मिलने वाली अदरक-लहसुन जोड़ी का एक हिस्सा।"},origin:{en:"Grown widely across Madhya Pradesh, Rajasthan, and Gujarat, with numerous regional varieties differing in clove size.",hi:"मध्य प्रदेश, राजस्थान और गुजरात में व्यापक रूप से उगाया जाता है, कली के आकार में भिन्न कई क्षेत्रीय किस्मों के साथ।"},benefits:{en:"Traditionally credited in Ayurveda with warming, immunity-supporting properties, and used raw in small amounts for the strongest effect.",hi:"आयुर्वेद में परंपरागत रूप से गर्म तासीर और रोग प्रतिरोधक क्षमता सहायक गुणों का श्रेय दिया जाता है, सबसे तेज़ प्रभाव के लिए कच्चा थोड़ी मात्रा में उपयोग होता है।"},uses:{en:"Ginger-garlic paste, tempered whole in tadka, and roasted whole as an accompaniment to some regional dishes.",hi:"अदरक-लहसुन पेस्ट, तड़के में साबुत भूनी जाती है, और कुछ क्षेत्रीय व्यंजनों के साथ साबुत भुनी परोसी जाती है।"},tip:{en:"Smash garlic cloves with the flat of a knife before peeling — the skin comes off far more easily once the clove is slightly crushed.",hi:"छीलने से पहले लहसुन की कलियों को चाकू के चौड़े हिस्से से कुचलें — हल्का कुचलने पर छिलका कहीं ज़्यादा आसानी से उतरता है।"}}],FESTIVAL_FOODS=[{id:"diwali",emoji:"🪔",name:{en:"Diwali Sweets & Snacks",hi:"दिवाली की मिठाइयाँ और नाश्ता"},desc:{en:"The festival of lights is as much about food as diyas — homes fill with trays of mithai to share with family, friends, and neighbors.",hi:"रोशनी का त्योहार दीयों जितना ही खाने के बारे में भी है — घर मिठाइयों की थालियों से भर जाते हैं, परिवार, दोस्तों और पड़ोसियों के साथ बाँटने के लिए।"},origin:{en:"Celebrated across nearly all of India in autumn, though the specific sweets made vary strongly by region and family tradition.",hi:"लगभग पूरे भारत में पतझड़ में मनाया जाता है, हालांकि बनाई जाने वाली खास मिठाइयाँ क्षेत्र और पारिवारिक परंपरा के अनुसार काफ़ी अलग होती हैं।"},benefits:{en:"The occasion for the year's most elaborate homemade sweets, often made together as a family in the days leading up to the festival.",hi:"साल की सबसे विस्तृत घर की बनी मिठाइयों का अवसर, अक्सर त्योहार से पहले के दिनों में परिवार साथ मिलकर बनाता है।"},uses:{en:"Besan ladoo, kaju katli, gujiya, and namkeen mixtures like chivda are exchanged as gifts between homes.",hi:"बेसन लड्डू, काजू कतली, गुजिया, और चिवड़ा जैसे नमकीन मिश्रण घरों के बीच उपहार के रूप में बाँटे जाते हैं।"},tip:{en:"Making sweets a few days ahead in batches and storing them in airtight containers is how most households manage the volume needed for guests.",hi:"कुछ दिन पहले बैचों में मिठाई बनाना और एयरटाइट डिब्बों में रखना ही ज़्यादातर घर मेहमानों के लिए ज़रूरी मात्रा संभालते हैं।"}},{id:"holi",emoji:"🎨",name:{en:"Holi Gujiya & Thandai",hi:"होली की गुजिया और ठंडाई"},desc:{en:"The festival of colors pairs its playful chaos with two signature foods: sweet stuffed gujiya and a spiced, nutty cold milk drink.",hi:"रंगों का त्योहार अपनी मस्ती भरी अफ़रा-तफ़री को दो खास खानों के साथ जोड़ता है: मीठी भरी गुजिया और मसालेदार, मेवेदार ठंडा दूध।"},origin:{en:"Celebrated across North India in spring, with gujiya especially central to Uttar Pradesh, Rajasthan, and Madhya Pradesh households.",hi:"उत्तर भारत में वसंत ऋतु में मनाया जाता है, गुजिया विशेष रूप से उत्तर प्रदेश, राजस्थान और मध्य प्रदेश के घरों में केंद्रीय है।"},benefits:{en:"Thandai's mix of nuts, seeds, and spices is traditionally seen as cooling and energizing for a day spent outdoors in the sun.",hi:"ठंडाई में मेवे, बीज और मसालों का मिश्रण धूप में बाहर बिताए दिन के लिए परंपरागत रूप से ठंडक और ऊर्जा देने वाला माना जाता है।"},uses:{en:"Gujiya (fried dumplings stuffed with khoya and dry fruits) and glasses of chilled thandai shared among family and friends.",hi:"गुजिया (खोया और मेवे भरी तली लोइयाँ) और परिवार-दोस्तों के साथ बाँटे गए ठंडाई के गिलास।"},tip:{en:"Seal gujiya edges firmly with a fork or by pinching a decorative twist — an improperly sealed gujiya will burst open and leak filling while frying.",hi:"गुजिया के किनारों को कांटे से या सजावटी मोड़ से अच्छी तरह बंद करें — ठीक से बंद न की गई गुजिया तलते समय फट कर भरावन बहा देती है।"}},{id:"navratri",emoji:"🙏",name:{en:"Navratri Fasting Food",hi:"नवरात्रि व्रत का भोजन"},desc:{en:"Nine nights of fasting built around a specific set of permitted grains and vegetables, avoiding regular wheat, rice, onion, and garlic.",hi:"नौ रातों का व्रत जो अनुमत अनाजों और सब्ज़ियों के खास समूह के इर्द-गिर्द बना है, सामान्य गेहूं, चावल, प्याज़ और लहसुन से परहेज़ करते हुए।"},origin:{en:"Observed across India in the honor of Goddess Durga, with regional variations in exact dietary rules between North and West India.",hi:"देवी दुर्गा के सम्मान में पूरे भारत में मनाया जाता है, उत्तर और पश्चिम भारत के बीच सटीक आहार नियमों में क्षेत्रीय भिन्नताएँ हैं।"},benefits:{en:"The fast is traditionally seen as both a spiritual discipline and a period of lighter, easily digestible eating for the body.",hi:"व्रत परंपरागत रूप से आध्यात्मिक अनुशासन और शरीर के लिए हल्के, आसानी से पचने वाले खाने की अवधि दोनों माना जाता है।"},uses:{en:"Sabudana khichdi, kuttu ki puri, singhare ka halwa, and vrat-friendly potato dishes seasoned with rock salt (sendha namak).",hi:"साबूदाना खिचड़ी, कुट्टू की पूरी, सिंघाड़े का हलवा, और सेंधा नमक से बने व्रत-अनुकूल आलू के व्यंजन।"},tip:{en:"Keep a stock of vrat-approved ingredients — kuttu atta, sabudana, singhare atta, and sendha namak — ready before the nine days begin.",hi:"नौ दिन शुरू होने से पहले व्रत-स्वीकृत सामग्री — कुट्टू आटा, साबूदाना, सिंघाड़े का आटा और सेंधा नमक — तैयार रखें।"}},{id:"eid",emoji:"🌙",name:{en:"Eid Sheer Khurma & Biryani",hi:"ईद की शीर खुरमा और बिरयानी"},desc:{en:"After a month of fasting through Ramzan, Eid opens with a rich vermicelli milk dessert and closes big meals with festive biryani.",hi:"रमज़ान के एक महीने के व्रत के बाद, ईद एक समृद्ध सेवइयों वाली दूध की मिठाई से शुरू होती है और उत्सवी बिरयानी के साथ बड़े भोजन का समापन करती है।"},origin:{en:"Celebrated across India's Muslim communities, with especially elaborate food traditions in Hyderabad, Lucknow, and Delhi.",hi:"भारत के मुस्लिम समुदायों में मनाया जाता है, हैदराबाद, लखनऊ और दिल्ली में विशेष रूप से विस्तृत खाने की परंपराओं के साथ।"},benefits:{en:"Sheer khurma's dates and nuts offer a quick, nourishing way to break a month of fasting gently.",hi:"शीर खुरमा के खजूर और मेवे एक महीने के व्रत को धीरे से तोड़ने का त्वरित, पौष्टिक तरीका देते हैं।"},uses:{en:"Sheer khurma (vermicelli in sweetened milk with dates and nuts) for the morning, and mutton or chicken biryani for the main Eid feast.",hi:"सुबह के लिए शीर खुरमा (खजूर-मेवे के साथ मीठे दूध में सेवइयाँ), और मुख्य ईद भोज के लिए मटन या चिकन बिरयानी।"},tip:{en:"Toast the vermicelli in ghee until golden before adding milk for sheer khurma — this is what gives the dessert its signature nutty depth.",hi:"शीर खुरमा के लिए दूध डालने से पहले सेवइयों को घी में सुनहरा होने तक भूनें — यही मिठाई को उसकी खास मेवेदार गहराई देता है।"}},{id:"rakshabandhan",emoji:"🧵",name:{en:"Raksha Bandhan Sweets",hi:"रक्षाबंधन की मिठाइयाँ"},desc:{en:"A festival celebrating the sibling bond, marked by tying a rakhi and offering sweets as part of the ritual exchange.",hi:"भाई-बहन के बंधन का त्योहार, राखी बाँधने और अनुष्ठान के हिस्से के रूप में मिठाई देने के साथ मनाया जाता है।"},origin:{en:"Celebrated across North and West India in the monsoon month of Shravan, with sweets often bought fresh rather than homemade.",hi:"उत्तर और पश्चिम भारत में मानसून के श्रावण महीने में मनाया जाता है, मिठाइयाँ अक्सर घर की बजाय ताज़ी खरीदी जाती हैं।"},benefits:{en:"The sweet exchange itself carries symbolic value in the ritual, marking affection and the promise of protection between siblings.",hi:"मीठा आदान-प्रदान अनुष्ठान में प्रतीकात्मक महत्व रखता है, भाई-बहनों के बीच स्नेह और सुरक्षा के वादे को दर्शाता है।"},uses:{en:"Rasgulla, kaju katli, and barfi are the most common sweets exchanged when a rakhi is tied.",hi:"राखी बाँधते समय रसगुल्ला, काजू कतली और बर्फी सबसे आम मिठाइयाँ हैं जो दी जाती हैं।"},tip:{en:"Sweets with a longer shelf life, like barfi and kaju katli, travel and keep better than milk-based sweets like rasgulla if being sent by post to distant siblings.",hi:"बर्फी और काजू कतली जैसी लंबे समय तक टिकने वाली मिठाइयाँ, दूर रहने वाले भाई-बहनों को डाक से भेजने पर रसगुल्ले जैसी दूध की मिठाइयों से बेहतर टिकती हैं।"}},{id:"makarsankranti",emoji:"🪁",name:{en:"Makar Sankranti Til-Gud",hi:"मकर संक्रांति का तिल-गुड़"},desc:{en:"A harvest festival marked by sesame and jaggery sweets, eaten as both a treat and a symbolic wish for sweetness in relationships.",hi:"फसल कटाई का त्योहार जो तिल-गुड़ की मिठाइयों से मनाया जाता है, स्वाद के लिए और रिश्तों में मिठास की प्रतीकात्मक कामना दोनों के लिए खाई जाती हैं।"},origin:{en:"Celebrated across India under different names — Makar Sankranti, Lohri, Pongal, Bihu — timed to the sun's transit in mid-January.",hi:"भारत भर में अलग नामों से मनाया जाता है — मकर संक्रांति, लोहड़ी, पोंगल, बिहू — जनवरी के मध्य में सूर्य के संक्रमण के अनुसार।"},benefits:{en:"Sesame and jaggery are traditionally considered warming foods, well suited to the cold January weather when the festival falls.",hi:"तिल और गुड़ परंपरागत रूप से गर्म तासीर वाले खाद्य माने जाते हैं, त्योहार के समय जनवरी की ठंड के लिए उपयुक्त।"},uses:{en:'Til laddoo and gajak (sesame-jaggery brittle) are exchanged with the saying "eat sweet, talk sweet."',hi:'तिल के लड्डू और गजक (तिल-गुड़ की चिक्की) "तिल गुड़ खाओ, मीठा-मीठा बोलो" कहकर बाँटे जाते हैं।'},tip:{en:"Work quickly while the jaggery syrup is still hot when shaping til laddoo — it hardens fast and becomes difficult to mold once it cools.",hi:"तिल के लड्डू बनाते समय जब तक गुड़ की चाशनी गरम हो तभी जल्दी काम करें — यह ठंडा होने पर जल्दी सख़्त हो जाती है और आकार देना मुश्किल हो जाता है।"}},{id:"ganeshchaturthi",emoji:"🐘",name:{en:"Ganesh Chaturthi Modak",hi:"गणेश चतुर्थी के मोदक"},desc:{en:"Steamed or fried rice-flour dumplings filled with sweet coconut and jaggery, believed to be Lord Ganesha's favorite offering.",hi:"नारियल और गुड़ की मीठी भरावन से भरी भाप में पकी या तली चावल के आटे की लोइयाँ, भगवान गणेश का प्रिय भोग मानी जाती हैं।"},origin:{en:"Central to the festival across Maharashtra and Goa especially, where Ganesh Chaturthi is celebrated with particular grandeur.",hi:"विशेष रूप से महाराष्ट्र और गोवा में त्योहार का केंद्र, जहाँ गणेश चतुर्थी विशेष भव्यता से मनाई जाती है।"},benefits:{en:"The steamed version (ukadiche modak) is lighter than the fried variety, and coconut-jaggery filling provides quick natural energy.",hi:"भाप में पका मोदक (उकडीचे मोदक) तले मोदक से हल्का होता है, और नारियल-गुड़ की भरावन त्वरित प्राकृतिक ऊर्जा देती है।"},uses:{en:"Offered first to the Ganesha idol during puja, then shared as prasad among family and visitors.",hi:"पूजा के दौरान पहले गणेश प्रतिमा को अर्पित किया जाता है, फिर परिवार और आगंतुकों के बीच प्रसाद के रूप में बाँटा जाता है।"},tip:{en:"Knead the rice-flour dough with hot water and cover it while shaping — it dries and cracks quickly if left exposed to air.",hi:"चावल के आटे को गरम पानी से गूंधें और आकार देते समय ढँककर रखें — खुली हवा में जल्दी सूखकर फटने लगता है।"}},{id:"pongal",emoji:"☀️",name:{en:"Pongal Harvest Sweet",hi:"पोंगल की मीठी पोंगल"},desc:{en:"A Tamil harvest festival named after the sweet rice-and-lentil dish traditionally cooked to overflow from the pot as a sign of abundance.",hi:"तमिल फसल त्योहार जिसका नाम उस मीठे चावल-दाल व्यंजन से आया है, जिसे परंपरागत रूप से समृद्धि के संकेत के रूप में बर्तन से उफनते हुए पकाया जाता है।"},origin:{en:"Celebrated across Tamil Nadu each January, marking the sun's northward journey and the rice harvest.",hi:"हर जनवरी तमिलनाडु में मनाया जाता है, सूर्य की उत्तरायण यात्रा और चावल की फसल का प्रतीक।"},benefits:{en:"Sakkarai pongal combines rice, moong dal, jaggery, and ghee into an energy-dense dish appropriate for a day of celebration.",hi:"शक्करई पोंगल चावल, मूंग दाल, गुड़ और घी को मिलाकर एक उत्सव के दिन के लिए उपयुक्त ऊर्जा-सघन व्यंजन बनाता है।"},uses:{en:"Sakkarai pongal (sweet) offered first to the sun god, alongside savory ven pongal shared through the day.",hi:"शक्करई पोंगल (मीठा) पहले सूर्य देव को अर्पित किया जाता है, दिन भर नमकीन वेन पोंगल के साथ बाँटा जाता है।"},tip:{en:"Letting the pot boil over slightly when the rice and milk are cooking is considered an auspicious sign, not a mistake — it symbolizes abundance for the year ahead.",hi:"चावल-दूध पकते समय बर्तन का थोड़ा उफनना गलती नहीं बल्कि शुभ संकेत माना जाता है — यह आने वाले साल की समृद्धि का प्रतीक है।"}}],KITCHEN_TOOLS=[{id:"kadai",wiki:"Kadai",emoji:"🍲",name:{en:"Kadai (Wok-Style Pan)",hi:"कड़ाही"},desc:{en:"A deep, round-bottomed pan, the Indian kitchen's equivalent of a wok, ideal for deep-frying and slow-simmering gravies alike.",hi:"गहरा, गोल तले वाला बर्तन, भारतीय रसोई का वोक के समान, गहरा तलने और धीमी आँच पर ग्रेवी पकाने दोनों के लिए आदर्श।"},origin:{en:"Used across every Indian region for centuries, traditionally made of iron and now also available in stainless steel and non-stick.",hi:"सदियों से हर भारतीय क्षेत्र में उपयोग होता है, परंपरागत रूप से लोहे का बना, अब स्टेनलेस स्टील और नॉन-स्टिक में भी उपलब्ध।"},benefits:{en:"The rounded shape allows oil to pool deep in the center, requiring less oil overall than a flat pan for the same frying depth.",hi:"गोल आकार तेल को केंद्र में गहराई तक इकट्ठा होने देता है, समान तलने की गहराई के लिए चपटे बर्तन से कुल मिलाकर कम तेल चाहिए।"},uses:{en:"Deep-frying pakoras and puris, and simmering gravies like paneer butter masala and kadai paneer.",hi:"पकौड़े और पूरियाँ गहरी तलने के लिए, और पनीर बटर मसाला व कड़ाही पनीर जैसी ग्रेवी पकाने के लिए।"},tip:{en:"A well-seasoned iron kadai develops a natural non-stick surface over time and adds a small amount of dietary iron to food cooked in it.",hi:"अच्छी तरह पकाई गई लोहे की कड़ाही समय के साथ प्राकृतिक नॉन-स्टिक सतह विकसित करती है और उसमें पके खाने में थोड़ा आयरन भी जोड़ती है।"}},{id:"tawa",wiki:"Tawa",emoji:"🫓",name:{en:"Tawa (Flat Griddle)",hi:"तवा"},desc:{en:"A flat or slightly concave griddle used for roti, paratha, and dosa — one of the most essential tools in any Indian kitchen.",hi:"चपटा या हल्का गड्ढेदार तवा जो रोटी, पराठा और डोसा के लिए उपयोग होता है — किसी भी भारतीय रसोई के सबसे ज़रूरी बर्तनों में से एक।"},origin:{en:"Used across India for millennia, traditionally cast iron, though non-stick and aluminum versions are common today.",hi:"हज़ारों वर्षों से भारत भर में उपयोग होता है, परंपरागत रूप से कास्ट आयरन, हालांकि आज नॉन-स्टिक और एल्युमिनियम संस्करण भी आम हैं।"},benefits:{en:"A cast-iron tawa retains heat evenly, which is part of why rotis puff up properly on it rather than cooking unevenly.",hi:"कास्ट आयरन तवा गर्मी को समान रूप से बनाए रखता है, यही कारण है कि इस पर रोटियाँ ठीक से फूलती हैं, असमान नहीं पकतीं।"},uses:{en:"Cooking roti, paratha, and dosa, and also used for dry-roasting spices before grinding.",hi:"रोटी, पराठा और डोसा पकाने के लिए, और पीसने से पहले मसाले सूखा भूनने के लिए भी उपयोग होता है।"},tip:{en:"Heat the tawa thoroughly before the first roti goes on — a tawa that isn't hot enough is the most common reason rotis fail to puff.",hi:"पहली रोटी डालने से पहले तवे को अच्छी तरह गरम करें — पर्याप्त गरम न होना ही रोटियों के न फूलने का सबसे आम कारण है।"}},{id:"silbatta",wiki:"Mortar_and_pestle",emoji:"⚫",name:{en:"Sil Batta (Stone Mortar & Pestle)",hi:"सिलबट्टा"},desc:{en:"A flat grinding stone and a hand-held stone roller, used to grind fresh masalas and chutneys the traditional way.",hi:"चपटा पीसने वाला पत्थर और हाथ में पकड़ा जाने वाला पत्थर का रोलर, ताज़े मसाले और चटनी पारंपरिक तरीके से पीसने के लिए उपयोग होता है।"},origin:{en:"One of the oldest food preparation tools in India, still found in many kitchens alongside modern electric grinders.",hi:"भारत के सबसे पुराने खाना तैयार करने के औज़ारों में से एक, आधुनिक इलेक्ट्रिक ग्राइंडर के साथ आज भी कई रसोइयों में मिलता है।"},benefits:{en:"Grinding by hand generates less heat than an electric blender, which many cooks feel preserves the fresher, sharper flavor of raw spices.",hi:"हाथ से पीसने में इलेक्ट्रिक ब्लेंडर से कम गर्मी बनती है, जिसे कई रसोइये कच्चे मसालों का ताज़ा, तीखा स्वाद बचाए रखने वाला मानते हैं।"},uses:{en:"Grinding fresh masala pastes, chutneys, and traditionally used to make fine spice powders in bulk.",hi:"ताज़ा मसाला पेस्ट, चटनी पीसने के लिए, और परंपरागत रूप से बड़ी मात्रा में बारीक मसाला पाउडर बनाने के लिए उपयोग होता है।"},tip:{en:'A new sil batta needs to be "cured" by grinding rice and discarding it a few times — this removes any loose stone dust before it\'s used for actual cooking.',hi:'नए सिलबट्टे को चावल पीसकर कुछ बार फेंकते हुए "तैयार" करना पड़ता है — इससे असली खाना पकाने से पहले पत्थर की ढीली धूल निकल जाती है।'}},{id:"pressurecooker",wiki:"Pressure_cooking",emoji:"♨️",name:{en:"Pressure Cooker",hi:"प्रेशर कुकर"},desc:{en:"A sealed pot that cooks under pressure, cutting cooking time drastically for dals, rajma, and rice in nearly every Indian kitchen.",hi:"दबाव में पकाने वाला बंद बर्तन, दाल, राजमा और चावल के पकाने के समय को काफ़ी कम कर देता है, लगभग हर भारतीय रसोई में मौजूद।"},origin:{en:"Widely adopted across India starting in the mid-20th century, now considered an essential appliance in almost every home.",hi:"20वीं सदी के मध्य से भारत भर में व्यापक रूप से अपनाया गया, अब लगभग हर घर में ज़रूरी उपकरण माना जाता है।"},benefits:{en:"Cuts cooking time and fuel use significantly, and the shorter, hotter cooking preserves more nutrients in some vegetables than long boiling.",hi:"पकाने के समय और ईंधन उपयोग को काफ़ी कम करता है, और छोटा, गरम पकाना लंबे उबालने से कुछ सब्ज़ियों में ज़्यादा पोषक तत्व बचाता है।"},uses:{en:"Cooking dal, rajma, chole, and rice quickly, and tenderizing tougher cuts of meat in a fraction of the usual time.",hi:"दाल, राजमा, छोले और चावल जल्दी पकाने के लिए, और सख़्त मांस को सामान्य समय के एक अंश में नरम करने के लिए।"},tip:{en:'Count whistles rather than clock minutes for most home recipes — most dals and rajma are timed by "3 whistles" or "4 whistles" in Indian cooking tradition.',hi:'ज़्यादातर घरेलू रेसिपी में मिनट की बजाय सीटियाँ गिनें — भारतीय खाना पकाने की परंपरा में ज़्यादातर दाल और राजमा "3 सीटी" या "4 सीटी" से समय तय होते हैं।'}},{id:"chaklabelan",wiki:"Rolling_pin",emoji:"🥖",name:{en:"Chakla-Belan (Rolling Board & Pin)",hi:"चकला-बेलन"},desc:{en:"A round wooden board paired with a rolling pin, the simple duo behind every roti, paratha, and puri rolled out by hand.",hi:"गोल लकड़ी का पटा और बेलन की जोड़ी, हाथ से बेली गई हर रोटी, पराठे और पूरी के पीछे की सादा जोड़ी।"},origin:{en:"A staple in every Indian kitchen, traditionally made of wood, though marble and steel versions are also used today.",hi:"हर भारतीय रसोई का मुख्य हिस्सा, परंपरागत रूप से लकड़ी का बना, हालांकि आज संगमरमर और स्टील के संस्करण भी उपयोग होते हैं।"},benefits:{en:"A wooden chakla-belan doesn't transfer excess heat or cold to the dough, keeping it at an even, workable temperature while rolling.",hi:"लकड़ी का चकला-बेलन आटे में अतिरिक्त गर्मी या ठंडक नहीं जोड़ता, बेलते समय इसे समान, काम करने योग्य तापमान पर रखता है।"},uses:{en:"Rolling out roti, paratha, puri, and pastry dough for snacks like kachori and samosa.",hi:"रोटी, पराठा, पूरी और कचौरी-समोसे जैसे नाश्तों का आटा बेलने के लिए।"},tip:{en:"Dust the board lightly with dry flour before rolling, not oil — too much oil makes the dough slip unevenly instead of rolling out to a uniform round.",hi:"बेलने से पहले पटे पर तेल की बजाय हल्का सूखा आटा छिड़कें — ज़्यादा तेल आटे को असमान रूप से फिसलाता है, समान गोल आकार नहीं बनने देता।"}},{id:"tandoor",wiki:"Tandoor",emoji:"🔥",name:{en:"Tandoor (Clay Oven)",hi:"तंदूर"},desc:{en:"A cylindrical clay oven heated by charcoal or wood, capable of intense, dry heat that gives tandoori food its signature char.",hi:"चारकोल या लकड़ी से गरम बेलनाकार मिट्टी का ओवन, तेज़, सूखी गर्मी देने में सक्षम जो तंदूरी खाने को उसका खास कोयलापन देता है।"},origin:{en:"Rooted in Punjab, brought to prominence across India after Partition when tandoor cooks migrated and opened restaurants nationwide.",hi:"पंजाब में जड़ें, विभाजन के बाद पूरे भारत में प्रसिद्ध हुआ जब तंदूर के रसोइये देश भर में प्रवास कर रेस्टोरेंट खोलने लगे।"},benefits:{en:"Cooking at very high heat for a short time seals in juices while charring the outside, a technique difficult to replicate on a stovetop.",hi:"बहुत तेज़ आँच पर कम समय पकाना रस को अंदर बंद रखता है जबकि बाहर से कोयला बनाता है, यह तकनीक चूल्हे पर दोहराना मुश्किल है।"},uses:{en:"Tandoori chicken, seekh kebab, naan, and roti — all cooked stuck to the oven's hot inner walls.",hi:"तंदूरी चिकन, सीख कबाब, नान और रोटी — सभी ओवन की गरम भीतरी दीवारों पर चिपकाकर पकाए जाते हैं।"},tip:{en:"Restaurants often skewer meat vertically inside the tandoor rather than laying it flat — this ensures even exposure to the intense radiant heat on all sides.",hi:"रेस्टोरेंट अक्सर मांस को तंदूर के अंदर सीधा टाँगते हैं, चपटा नहीं रखते — इससे सभी तरफ़ तेज़ विकिरण गर्मी समान रूप से लगती है।"}},{id:"idlistand",wiki:"Idli",emoji:"⚪",name:{en:"Idli Stand",hi:"इडली स्टैंड"},desc:{en:"A stacked, multi-tray steaming rack designed to cook several idlis at once over boiling water without direct contact.",hi:"एक के ऊपर एक रखी गई बहु-ट्रे भाप देने वाली रैक जो उबलते पानी के ऊपर बिना सीधे संपर्क के एक साथ कई इडली पकाने के लिए बनाई गई है।"},origin:{en:"A South Indian kitchen essential, especially in Tamil Nadu, Karnataka, and Andhra Pradesh, where idli is a daily breakfast staple.",hi:"दक्षिण भारतीय रसोई की ज़रूरी चीज़, विशेष रूप से तमिलनाडु, कर्नाटक और आंध्र प्रदेश में, जहाँ इडली रोज़ाना का नाश्ता है।"},benefits:{en:"Steaming rather than frying keeps idli one of the lightest, oil-free breakfast options in Indian cooking.",hi:"तलने की बजाय भाप में पकाना इडली को भारतीय खाने में सबसे हल्के, तेल-रहित नाश्ते के विकल्पों में से एक बनाए रखता है।"},uses:{en:"Steaming fermented idli batter into soft, spongy idlis, usually 4-6 at a time per stand.",hi:"किण्वित इडली घोल को भाप देकर नरम, स्पंजी इडली बनाने के लिए, आमतौर पर एक स्टैंड में एक बार में 4-6 इडली।"},tip:{en:"Grease each mold lightly before pouring batter — this is what lets the steamed idli pop out cleanly instead of sticking and tearing.",hi:"घोल डालने से पहले हर साँचे में हल्का चिकनाई लगाएँ — इसी से भाप में पकी इडली फटने की बजाय साफ़ निकल आती है।"}},{id:"bilona",wiki:"Churning_(butter)",emoji:"🌀",name:{en:"Bilona (Wooden Churner)",hi:"बिलौना (मथानी)"},desc:{en:"A long wooden churning tool, twisted rapidly by hand with a rope, used to separate homemade butter from curd or cream.",hi:"लंबा लकड़ी का मथानी औज़ार, रस्सी से हाथ से तेज़ी से घुमाया जाता है, दही या क्रीम से घर का मक्खन अलग करने के लिए उपयोग होता है।"},origin:{en:"One of India's oldest dairy tools, still used in many rural and traditional homes despite the availability of electric churners.",hi:"भारत के सबसे पुराने डेयरी औज़ारों में से एक, इलेक्ट्रिक मथने वाले उपलब्ध होने के बावजूद कई ग्रामीण और पारंपरिक घरों में आज भी उपयोग होता है।"},benefits:{en:"Hand-churning at a controlled pace is traditionally believed to yield better-textured makhan than fast electric mixing.",hi:"नियंत्रित गति से हाथ से मथना परंपरागत रूप से तेज़ इलेक्ट्रिक मिक्सिंग से बेहतर बनावट वाला मक्खन देने वाला माना जाता है।"},uses:{en:"Churning curd or cream into fresh white butter (makhan), leaving behind the buttermilk (chaas) as a byproduct.",hi:"दही या क्रीम मथकर ताज़ा सफ़ेद मक्खन बनाने के लिए, उपोत्पाद के रूप में छाछ पीछे रह जाती है।"},tip:{en:"Chill the curd or cream before churning — starting cold separates the butter from the buttermilk far more cleanly than churning at room temperature.",hi:"मथने से पहले दही या क्रीम को ठंडा करें — ठंडे से शुरू करना कमरे के तापमान से मथने की तुलना में मक्खन को छाछ से कहीं ज़्यादा साफ़ अलग करता है।"}}],MORNING_DRINKS=[{id:"jeerapaani",emoji:"🌰",name:{en:"Jeera Paani (Cumin Water)",hi:"जीरा पानी"},desc:{en:"Toasted cumin seeds steeped overnight in water, a classic empty-stomach morning ritual in most Indian homes.",hi:"भुने जीरे को रातभर पानी में भिगोकर बनाया गया — ज़्यादातर भारतीय घरों में खाली पेट पीने की परंपरा।"},howToMake:{en:"Soak 1 tsp cumin seeds in a glass of water overnight. In the morning, boil for 2-3 minutes, strain, and sip warm. Or simply drink the strained soaking water at room temperature.",hi:"1 छोटा चम्मच जीरा एक गिलास पानी में रातभर भिगोएँ। सुबह 2-3 मिनट उबालें, छानें और गुनगुना पिएँ। या भीगा हुआ पानी छानकर सामान्य तापमान पर भी पी सकते हैं।"},benefits:{en:"Traditionally taken to support digestion and ease bloating; in Ayurveda it is considered warming and gently stimulating to appetite.",hi:"परंपरागत रूप से पाचन में सहायक और पेट फूलने में राहत के लिए लिया जाता है; आयुर्वेद में इसे गर्म तासीर वाला और भूख बढ़ाने वाला माना जाता है।"},bestTime:{en:"Empty stomach, first thing in the morning.",hi:"सुबह खाली पेट, सबसे पहले।"},tip:{en:"Lightly toasting the seeds before soaking deepens the flavor and is the more traditional method.",hi:"भिगोने से पहले जीरे को हल्का भूनना स्वाद बढ़ाता है और यह ज़्यादा पारंपरिक तरीका है।"}},{id:"dhaniyapaani",emoji:"🌿",name:{en:"Dhaniya Paani (Coriander Seed Water)",hi:"धनिया पानी"},desc:{en:"Whole coriander seeds soaked overnight, strained into a light, faintly citrusy morning drink.",hi:"साबुत धनिया के बीज रातभर भिगोकर बनाया गया हल्का, हल्का खट्टापन लिए सुबह का पेय।"},howToMake:{en:"Soak 1-2 tbsp whole coriander seeds in a glass of water overnight, covered. Strain in the morning and drink at room temperature, or simmer briefly if you prefer it warm.",hi:"1-2 बड़े चम्मच साबुत धनिया के बीज एक गिलास पानी में ढककर रातभर भिगोएँ। सुबह छानकर सामान्य तापमान पर पिएँ, या गुनगुना पसंद हो तो थोड़ा उबाल लें।"},benefits:{en:"Traditionally used to support digestion and considered a cooling drink in Ayurveda, often favored in warmer months.",hi:"परंपरागत रूप से पाचन में सहायक और आयुर्वेद में इसे ठंडी तासीर वाला पेय माना जाता है, अक्सर गर्मी के मौसम में पसंद किया जाता है।"},bestTime:{en:"Empty stomach, morning.",hi:"खाली पेट, सुबह।"},tip:{en:"Crush the seeds slightly before soaking to release more flavor into the water.",hi:"भिगोने से पहले बीजों को हल्का कुचल लें, इससे पानी में स्वाद ज़्यादा उतरता है।"}},{id:"amlapaani",emoji:"🟢",name:{en:"Amla Paani (Indian Gooseberry Water)",hi:"आँवला पानी"},desc:{en:"Fresh amla juice or soaked dried amla diluted in water — one of Ayurveda's most celebrated morning tonics.",hi:"ताज़े आँवले का रस या भिगोया सूखा आँवला पानी में मिलाकर — आयुर्वेद के सबसे प्रसिद्ध सुबह के टॉनिकों में से एक।"},howToMake:{en:"Blend 1-2 fresh amla (deseeded) with a cup of water and strain, or soak 1 tsp dried amla powder overnight and stir well in the morning. Add a little honey if desired.",hi:"1-2 ताज़े आँवले (बीज निकालकर) एक कप पानी के साथ पीसकर छान लें, या 1 छोटा चम्मच सूखा आँवला पाउडर रातभर भिगोकर सुबह अच्छी तरह मिलाएँ। चाहें तो थोड़ा शहद मिलाएँ।"},benefits:{en:"Amla is one of the richest natural sources of Vitamin C and is traditionally valued in Ayurveda for supporting immunity and digestion.",hi:"आँवला विटामिन C के सबसे समृद्ध प्राकृतिक स्रोतों में से एक है और आयुर्वेद में रोग प्रतिरोधक क्षमता और पाचन के लिए पारंपरिक रूप से महत्वपूर्ण माना जाता है।"},bestTime:{en:"Empty stomach, morning.",hi:"खाली पेट, सुबह।"},tip:{en:"Amla juice is quite tart — starting with a smaller, diluted amount makes it easier to build into a daily habit.",hi:"आँवले का रस काफ़ी खट्टा होता है — शुरुआत में कम और ज़्यादा पतला रखना इसे रोज़ की आदत बनाना आसान करता है।"}},{id:"ajwainpaani",emoji:"⚪",name:{en:"Ajwain Paani (Carom Seed Water)",hi:"अजवाइन पानी"},desc:{en:"A sharp, slightly bitter infusion of carom seeds, reached for in most Indian kitchens whenever the stomach feels heavy.",hi:"अजवाइन का तीखा, हल्का कड़वा काढ़ा — पेट भारी लगने पर ज़्यादातर भारतीय रसोइयों में पहला उपाय।"},howToMake:{en:"Boil 1 tsp ajwain seeds in a cup of water for 3-5 minutes until the water turns light golden. Strain and sip warm.",hi:"1 छोटा चम्मच अजवाइन एक कप पानी में 3-5 मिनट उबालें जब तक पानी हल्का सुनहरा न हो जाए। छानकर गुनगुना पिएँ।"},benefits:{en:"One of the most common home remedies for gas and indigestion across Indian households; also traditionally used to ease a stuffy nose when taken warm.",hi:"भारतीय घरों में गैस और अपच के लिए सबसे आम घरेलू उपाय; गुनगुना लेने पर बंद नाक में राहत के लिए भी परंपरागत रूप से उपयोग होता है।"},bestTime:{en:"After a heavy meal, or first thing in the morning.",hi:"भारी भोजन के बाद, या सुबह सबसे पहले।"},tip:{en:"A pinch of black salt in the strained water is a common addition that many find settles the stomach further.",hi:"छाने हुए पानी में एक चुटकी काला नमक मिलाना आम है, जिससे कई लोगों को पेट और ज़्यादा हल्का महसूस होता है।"}},{id:"methipaani",emoji:"🟡",name:{en:"Methi Paani (Fenugreek Seed Water)",hi:"मेथी पानी"},desc:{en:"Fenugreek seeds soaked overnight, giving a slightly bitter water that is a staple morning remedy, especially valued around blood sugar balance.",hi:"रातभर भिगोए मेथी दाने — हल्का कड़वा पानी, विशेष रूप से रक्त शर्करा संतुलन के लिए एक जाना-पहचाना सुबह का उपाय।"},howToMake:{en:"Soak 1 tsp fenugreek seeds in a glass of water overnight. Strain in the morning and drink; the softened seeds can also be chewed.",hi:"1 छोटा चम्मच मेथी दाने एक गिलास पानी में रातभर भिगोएँ। सुबह छानकर पिएँ; नरम हुए दानों को चबाया भी जा सकता है।"},benefits:{en:"Widely used as a traditional home remedy that many believe supports healthy blood sugar levels and digestion; the seeds are also traditionally chewed for the same reason.",hi:"एक पारंपरिक घरेलू उपाय के रूप में व्यापक रूप से उपयोग होता है जिसे कई लोग स्वस्थ रक्त शर्करा स्तर और पाचन में सहायक मानते हैं; इसी वजह से दाने भी चबाए जाते हैं।"},bestTime:{en:"Empty stomach, morning.",hi:"खाली पेट, सुबह।"},tip:{en:"The taste is quite bitter — many people find it easier to start with half a teaspoon of seeds and work up gradually.",hi:"स्वाद काफ़ी कड़वा होता है — कई लोगों को आधा छोटा चम्मच दानों से शुरू कर धीरे-धीरे बढ़ाना आसान लगता है।"}},{id:"saunfpaani",emoji:"🌾",name:{en:"Saunf Paani (Fennel Seed Water)",hi:"सौंफ पानी"},desc:{en:"A mild, naturally sweet-tasting infusion of fennel seeds, gentle enough to be a favorite after-meal and morning drink alike.",hi:"सौंफ का हल्का, स्वाभाविक रूप से मीठा काढ़ा — इतना हल्का कि भोजन के बाद और सुबह दोनों समय पसंद किया जाता है।"},howToMake:{en:"Soak 1-2 tsp fennel seeds in a glass of water overnight, or boil them in water for 5 minutes for a quicker version. Strain and drink warm or at room temperature.",hi:"1-2 छोटा चम्मच सौंफ एक गिलास पानी में रातभर भिगोएँ, या जल्दी बनाने के लिए 5 मिनट उबालें। छानकर गुनगुना या सामान्य तापमान पर पिएँ।"},benefits:{en:"Traditionally used to freshen breath and support digestion; its naturally cooling, mild nature makes it one of the gentlest seed waters to start with.",hi:"परंपरागत रूप से मुँह की ताज़गी और पाचन में सहायक; स्वाभाविक रूप से ठंडी तासीर इसे शुरू करने के लिए सबसे हल्के बीज-पानी में से एक बनाती है।"},bestTime:{en:"Morning, or after meals.",hi:"सुबह, या भोजन के बाद।"},tip:{en:"A few crushed seeds release more flavor than whole ones — lightly crush them with a mortar and pestle before soaking.",hi:"हल्के कुचले हुए दाने साबुत दानों से ज़्यादा स्वाद देते हैं — भिगोने से पहले सिलबट्टे से हल्का कुचल लें।"}},{id:"kalonjipaani",emoji:"⚫",name:{en:"Kalonji Paani (Nigella Seed Water)",hi:"कलौंजी पानी"},desc:{en:"Nigella seeds steeped overnight into a smoky, slightly peppery water, less common but well known in Ayurvedic and Unani home remedies.",hi:"कलौंजी को रातभर भिगोकर बना धुएँदार, हल्का तीखा पानी — कम प्रचलित पर आयुर्वेदिक और यूनानी घरेलू उपायों में जाना-पहचाना।"},howToMake:{en:"Soak 1/2 tsp nigella seeds in a glass of water overnight. Strain in the morning and drink; a squeeze of lemon is a common addition.",hi:"1/2 छोटा चम्मच कलौंजी एक गिलास पानी में रातभर भिगोएँ। सुबह छानकर पिएँ; नींबू की कुछ बूँदें मिलाना आम है।"},benefits:{en:"Used in traditional Ayurvedic and Unani medicine and often described as supporting overall wellness; research on nigella seeds is ongoing.",hi:"पारंपरिक आयुर्वेदिक और यूनानी चिकित्सा में उपयोग होता है और अक्सर समग्र स्वास्थ्य में सहायक बताया जाता है; कलौंजी पर शोध जारी है।"},bestTime:{en:"Empty stomach, morning.",hi:"खाली पेट, सुबह।"},tip:{en:"The flavor is strong and slightly bitter — start with a smaller quantity of seeds until you know how you like it.",hi:"स्वाद तीखा और हल्का कड़वा होता है — पसंद जानने तक कम मात्रा में दानों से शुरुआत करें।"}},{id:"tulsipaani",emoji:"🍃",name:{en:"Tulsi Paani (Holy Basil Water)",hi:"तुलसी पानी"},desc:{en:"Fresh tulsi leaves steeped in warm water — one of the most common household remedies, rooted deeply in Ayurvedic tradition.",hi:"ताज़ी तुलसी की पत्तियाँ गरम पानी में भिगोकर — सबसे आम घरेलू उपायों में से एक, आयुर्वेदिक परंपरा में गहराई से जुड़ा।"},howToMake:{en:"Simmer 8-10 fresh tulsi leaves in a cup of water for 5 minutes. Strain and drink warm; ginger or honey can be added.",hi:"8-10 ताज़ी तुलसी की पत्तियाँ एक कप पानी में 5 मिनट उबालें। छानकर गुनगुना पिएँ; अदरक या शहद मिला सकते हैं।"},benefits:{en:"Tulsi is considered a sacred, adaptogenic herb in Ayurveda and is traditionally taken to support immunity and respiratory wellness, especially during seasonal changes.",hi:"आयुर्वेद में तुलसी को पवित्र और एडाप्टोजेनिक जड़ी-बूटी माना जाता है और परंपरागत रूप से रोग प्रतिरोधक क्षमता व श्वसन स्वास्थ्य के लिए, खासकर मौसम बदलने पर, ली जाती है।"},bestTime:{en:"Morning, or whenever a warm, soothing drink is welcome.",hi:"सुबह, या जब भी गरम, आरामदायक पेय अच्छा लगे।"},tip:{en:"A single crushed black peppercorn simmered along with the leaves adds warmth and is a common household addition during cold season.",hi:"पत्तियों के साथ एक कुचली काली मिर्च उबालना गर्मी बढ़ाता है और सर्दी के मौसम में एक आम घरेलू जोड़ है।"}},{id:"adrakpaani",emoji:"🫚",name:{en:"Adrak Paani (Ginger Water)",hi:"अदरक पानी"},desc:{en:"Fresh ginger simmered into a warming water, one of the most reached-for remedies in Indian homes for an unsettled stomach.",hi:"ताज़ा अदरक उबालकर बना गर्माहट भरा पानी — पेट खराब होने पर भारतीय घरों में सबसे ज़्यादा अपनाया जाने वाला उपाय।"},howToMake:{en:"Simmer a 1-inch piece of crushed fresh ginger in a cup of water for 5-7 minutes. Strain and sip warm; a little honey or lemon can be added once slightly cooled.",hi:"1 इंच कुचला हुआ ताज़ा अदरक एक कप पानी में 5-7 मिनट उबालें। छानकर गुनगुना पिएँ; थोड़ा ठंडा होने पर शहद या नींबू मिला सकते हैं।"},benefits:{en:"Traditionally used to ease nausea, support digestion, and provide warming relief for a cold or sore throat.",hi:"परंपरागत रूप से मतली में राहत, पाचन में सहायता और सर्दी या गले की खराश में गर्माहट भरी राहत के लिए उपयोग होता है।"},bestTime:{en:"Morning, or any time digestion feels off.",hi:"सुबह, या जब भी पाचन ठीक न लगे।"},tip:{en:"Add honey only after the water has cooled slightly — very hot liquid can break down some of honey's natural qualities.",hi:"शहद पानी के थोड़ा ठंडा होने के बाद ही मिलाएँ — बहुत गरम पानी में शहद के प्राकृतिक गुण कम हो सकते हैं।"}},{id:"haldipaani",emoji:"🟠",name:{en:"Haldi Paani (Turmeric Water)",hi:"हल्दी पानी"},desc:{en:"Warm water infused with turmeric — a lighter, dairy-free alternative to the more familiar haldi doodh (turmeric milk).",hi:"हल्दी मिला गरम पानी — जानी-पहचानी हल्दी दूध का हल्का, बिना दूध वाला विकल्प।"},howToMake:{en:"Stir 1/4 tsp turmeric powder and a pinch of black pepper into a cup of warm water. A squeeze of lemon and a little honey can be added.",hi:"1/4 छोटा चम्मच हल्दी पाउडर और एक चुटकी काली मिर्च एक कप गरम पानी में घोलें। नींबू की कुछ बूँदें और थोड़ा शहद मिला सकते हैं।"},benefits:{en:"Turmeric's curcumin is prized in Ayurveda for anti-inflammatory and antioxidant properties; black pepper is traditionally added because it is believed to help the body absorb curcumin better.",hi:"हल्दी का करक्यूमिन आयुर्वेद में सूजन-रोधी और एंटीऑक्सीडेंट गुणों के लिए प्रसिद्ध है; काली मिर्च परंपरागत रूप से इसलिए मिलाई जाती है क्योंकि माना जाता है कि यह शरीर को करक्यूमिन सोखने में मदद करती है।"},bestTime:{en:"Empty stomach, morning, or before bed.",hi:"खाली पेट, सुबह, या सोने से पहले।"},tip:{en:"A little goes a long way — too much turmeric can taste bitter and overpower the drink.",hi:"थोड़ी हल्दी ही काफ़ी है — ज़्यादा डालने से स्वाद कड़वा और भारी हो जाता है।"}},{id:"nimbushehadpaani",emoji:"🍋",name:{en:"Nimbu Shehad Paani (Lemon Honey Water)",hi:"नींबू शहद पानी"},desc:{en:"Warm water with fresh lemon juice and honey — perhaps the single most common morning drink across Indian households.",hi:"ताज़े नींबू के रस और शहद के साथ गरम पानी — शायद भारतीय घरों में सबसे आम सुबह का पेय।"},howToMake:{en:"Squeeze the juice of half a lemon and stir in 1 tsp honey into a cup of warm (not boiling) water. Drink right away.",hi:"आधे नींबू का रस निचोड़ें और 1 छोटा चम्मच शहद एक कप गरम (उबलते नहीं) पानी में मिलाएँ। तुरंत पिएँ।"},benefits:{en:"A simple, widely loved way to start the day with hydration and Vitamin C from the lemon; many also find it a gentle, soothing habit before breakfast.",hi:"नींबू से मिलने वाले विटामिन C और हाइड्रेशन के साथ दिन शुरू करने का एक सरल, बेहद पसंदीदा तरीका; कई लोगों को यह नाश्ते से पहले एक हल्की, आरामदायक आदत भी लगती है।"},bestTime:{en:"Empty stomach, first thing in the morning.",hi:"खाली पेट, सुबह सबसे पहले।"},tip:{en:"Use warm, not boiling water — very hot water can dull the lemon's fresh flavor and reduce honey's natural qualities.",hi:"उबलता नहीं, गुनगुना पानी इस्तेमाल करें — बहुत गरम पानी नींबू का ताज़ा स्वाद कम कर देता है और शहद के गुण घटा देता है।"}},{id:"jeeraamlapaani",emoji:"💧",name:{en:"Detox Water (Jeera-Amla-Ajwain Mix)",hi:"डिटॉक्स पानी (जीरा-आँवला-अजवाइन मिश्रण)"},desc:{en:"A combined overnight soak of cumin, dried amla, and carom seeds — a popular all-in-one morning tonic in many households.",hi:"जीरा, सूखा आँवला और अजवाइन का संयुक्त रातभर भिगोया मिश्रण — कई घरों में लोकप्रिय ऑल-इन-वन सुबह का टॉनिक।"},howToMake:{en:"Soak 1/2 tsp each of cumin seeds, dried amla pieces, and carom seeds together in a glass of water overnight. Strain in the morning and drink at room temperature.",hi:"1/2-1/2 छोटा चम्मच जीरा, सूखे आँवले के टुकड़े और अजवाइन एक गिलास पानी में रातभर एक साथ भिगोएँ। सुबह छानकर सामान्य तापमान पर पिएँ।"},benefits:{en:"Combines the traditional digestive and immunity-supporting reputations of its three ingredients into one easy morning routine.",hi:"तीनों सामग्रियों के पारंपरिक पाचन और रोग प्रतिरोधक क्षमता से जुड़े गुणों को एक आसान सुबह की दिनचर्या में जोड़ता है।"},bestTime:{en:"Empty stomach, morning.",hi:"खाली पेट, सुबह।"},tip:{en:"Prepare the soak the night before and keep it by your bedside — it becomes an easy habit once it's part of your evening routine.",hi:"रात को ही भिगोकर तैयार रखें और बिस्तर के पास रख दें — शाम की दिनचर्या का हिस्सा बनते ही यह आसान आदत बन जाती है।"}}];window.__learnExtraLoaded=!0,window.__onLearnExtraLoaded&&window.__onLearnExtraLoaded();